  (270, 1001, '[{\"MIGX_id\":\"13\",\"image\":\"gal7-min.jpg\"},{\"MIGX_id\":\"14\",\"image\":\"gal8-min.jpg\"},{\"MIGX_id\":\"6\",\"image\":\"gal1-min.jpg\"},{\"MIGX_id\":\"11\",\"image\":\"gal4-min.jpg\"},{\"MIGX_id\":\"10\",\"image\":\"gal3-min.jpg\"},{\"MIGX_id\":\"12\",\"image\":\"gal5-min.jpg\"},{\"MIGX_id\":\"9\",\"image\":\"gal2-min.jpg\"},{\"MIGX_id\":\"8\",\"image\":\"gal11-min.jpg\"},{\"MIGX_id\":\"7\",\"image\":\"gal10-min.jpg\"},{\"MIGX_id\":\"15\",\"image\":\"gal9-min.jpg\"}]'),
