INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1002, 'document', 'text/html', 'Eyebrow micropigmentation', 'Eyebrow micropigmentation in Bucharest, brow tattoo prices | LBar', 'Get eyebrow micropigmentation in Bucharest at Studio LBar. Artists with 5+ years of experience, modern techniques, affordable prices, natural results guaranteed', 'eyebrow-micropigmentation', '', 1, 0, 0, 1080, 1, '', '', 1, 8, 1, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Eyebrow micropigmentation', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'eyebrow-micropigmentation', 0, 0, 1, '{\"stercseo\":{\"index\":\"1\",\"follow\":\"1\",\"sitemap\":\"1\",\"priority\":\"0.5\",\"changefreq\":\"\"},\"core\":{\"responseCode\":\"HTTP\\/1.1 301 Moved Permanently\"},\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (22, 1002, 'img-cat-1.jpg'),
  (24, 1002, 'foto1-min.jpg'),
  (26, 1002, 'You can opt for eyebrow micropigmentation if you:'),
  (27, 1002, 'Want to give your brows a new shape'),
  (30, 1002, 'A tattoo helps create the right brow shape, disguising unruly, randomly growing natural hairs.'),
  (31, 1002, 'Photo gallery – eyebrow permanent makeup before and after the procedure'),
  (32, 1002, 'Price list: eyebrow micropigmentation in Bucharest'),
  (34, 1002, 'Eyebrow tattoo reviews from our <br>lovely clients at the studio</br>'),
  (35, 1002, 'Eyebrow micropigmentation'),
  (36, 1002, 'Contact'),
  (37, 1002, '[{\"MIGX_id\":\"1\",\"questions-title\":\"Is eyebrow micropigmentation in Bucharest painful?\",\"questions-text\":\"<p><span id=\\\"docs-internal-guid-272f9c14-7fff-b20c-e8f4-dbb76c9acc9d\\\"><span>The procedure can be considered painless thanks to the anesthetic and to the pigment being placed in the upper layers of the skin. You may feel a slight tingling during the process.<\\/span><\\/span><\\/p>\"},{\"MIGX_id\":\"2\",\"questions-title\":\"How long does the tattoo procedure take?\",\"questions-text\":\"<p><span id=\\\"docs-internal-guid-3261119b-7fff-e389-0956-86e3d13d7e29\\\"><span>From 1 hour 30 min to 2 hours, depending on the method. This includes the consultation, mapping the design and the procedure itself.<\\/span><\\/span><\\/p>\"},{\"MIGX_id\":\"3\",\"questions-title\":\"Can I have eyebrow micropigmentation during pregnancy?\",\"questions-text\":\"<p><span id=\\\"docs-internal-guid-6193c91f-7fff-3d2b-93ba-56646791f5dd\\\"><span>Yes, provided no anesthetic is used, as it is contraindicated for pregnant women. In this case, powder brows are the best option. All other techniques are done only with an anesthetic.<\\/span><\\/span><\\/p>\\n<p>\\u00a0<\\/p>\"},{\"MIGX_id\":\"4\",\"questions-title\":\"How do I choose an eyebrow micropigmentation technique? \",\"questions-text\":\"<p><span id=\\\"docs-internal-guid-06c28946-7fff-b488-e99f-2df50e9e0843\\\"><span>The technique is chosen based on your preferences. The most popular is the powder technique, which creates a soft ombr\\u00e9 effect. If you want to add volume to your brows or \\u201cdraw\\u201d them in, hair-stroke cosmetic tattooing can be an excellent solution. The hybrid technique suits those who want denser brows with a more intense shade.<\\/span><\\/span><\\/p>\\n<p>\\u00a0<\\/p>\"},{\"MIGX_id\":\"5\",\"questions-title\":\"How long does the tattoo last?\",\"questions-text\":\"<p><span id=\\\"docs-internal-guid-537c21ff-7fff-fff5-3d3f-db8e4d079ec0\\\"><span>For 1.5\\u20132 years. It depends on your skin type and age, your lifestyle, how well you care for the tattoo and whether you have the touch-up on schedule.<\\/span><\\/span><\\/p>\\n<p>\\u00a0<\\/p>\"}]'),
  (38, 1002, 'Eyebrow micropigmentation '),
  (39, 1002, 'Brows that catch the eye. Your perfect way to transform your look.'),
  (40, 1002, 'IMG_5877-min.jpg'),
  (41, 1002, '<p>A new concept in semi-permanent makeup<br />Techniques flawlessly performed by a TOP Master<br />Absolute safety and sterile equipment</p>'),
  (45, 1002, 'What does an eyebrow tattoo mean for you?'),
  (46, 1002, '<p>A way to change the shape of your brows? Or to transform your look with a flattering accent on your face? A chance to effectively hide imperfections in the brow area that bother or embarrass you? Whatever your reason, eyebrow permanent makeup can help. And it can all be done in an hour and a half, in a comfortable atmosphere at a modern studio. There is no need for doubts: an eyebrow tattoo is a completely painless and safe procedure. In fact, LBar studio makes every effort to give you service you\'ll love. Above all, the final result: gorgeous brows with a well-proportioned, modern shape and a natural shade, made just for you.</p>'),
  (47, 1002, 'Gorgeous brows from every angle. Choose between the powder, hair-stroke or hybrid technique. An amazing effect that lasts 2 years. '),
  (48, 1002, '1051,1052,1053,1054'),
  (49, 1002, 'Choose the technique that suits you, and we\'ll make sure it\'s done right'),
  (50, 1002, 'Choose your eyebrow tattoo technique'),
  (51, 1002, 'Need to hide imperfections'),
  (52, 1002, 'Scars, acne marks, psoriasis and any small flaws will become virtually invisible.'),
  (53, 1002, 'Want a new look'),
  (54, 1002, 'Semi-permanent eyebrow makeup gives your face a beautiful, delicate look. Your face looks fresh and well-groomed.'),
  (64, 1002, '[{\"MIGX_id\":\"1\",\"col-1\":\"Powder brows micropigmentation\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"2\",\"col-1\":\"Microblading brows\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"3\",\"col-1\":\"Hair-stroke eyebrow micropigmentation\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"5\",\"col-1\":\"3D\\/6D eyebrow micropigmentation\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"6\",\"col-1\":\"Hair-stroke technique\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"7\",\"col-1\":\"Touch-up\",\"col-2\":\"1 hour\",\"col-3\":\"\",\"col-4\":\"400 RON\"},{\"MIGX_id\":\"8\",\"col-1\":\"Correction of another artist\'s work\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"100% of the first session price\"},{\"MIGX_id\":\"9\",\"col-1\":\"Refresh within 1 year\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"80% of the original price\"}]'),
  (65, 1002, 'Answers to frequently asked questions'),
  (66, 1002, '/en/portfolio'),
  (67, 1002, 'Eyebrow tattoo – a great alternative to daily makeup'),
  (68, 1002, '<p>There is no more effective and affordable option for everyday makeup than a tattoo. <br />After a procedure of just 1 hour 30 min, you get semi-permanent brow makeup that stays put in any situation for at least 1 year. The shape and color stay the same, your face looks fresher, and your brows look modern and lovely. A complete change of look!<br />Eyebrow micropigmentation is the modern counterpart of older forms of tattooing. It uses mineral-based pigments that are placed in the upper layers of the skin, which is both safer and less painful for you. The pigment gradually breaks down and fades, which allows either a second touch-up to refresh the color or a switch to another technique or pigment shade. A perfect solution both for those who like to experiment with their look and for those who prefer consistency.</p>'),
  (69, 1002, '<h2>What are the benefits of eyebrow micropigmentation?</h2>\r\n<p>The tattooing procedure offers several valuable benefits at once. First of all, it is safe: as long as sterility requirements are met, the procedure carries absolutely no risk. What\'s more, it rules out the allergic reactions that can occur with decorative cosmetics. <br />From an aesthetic point of view, an eyebrow tattoo:</p>\r\n<ul>\r\n<li>helps create a beautiful shape with the right peak, arch and length – an excellent solution for anyone with asymmetrical brows or flaws in shape and thickness;</li>\r\n<li>makes brows visually easier to keep tidy, especially when coarse hairs grow in every direction – they will be less noticeable against a darker background;</li>\r\n<li>hides small flaws in the facial area: scars, acne marks, inflammation, etc.;</li>\r\n<li>saves you time on makeup and helps you feel confident anytime, anywhere.</li>\r\n</ul>\r\n<h2>Stages of the eyebrow micropigmentation procedure</h2>\r\n<p>Whatever technique you choose, the procedure begins with mapping the design. The artist sketches the outline and then uses it as a temporary guide to create a well-proportioned, modern and gorgeous brow shape. The design is always approved together with the client – a very important point.</p>\r\n<h3>What you should know</h3>\r\n<ul>\r\n<li>Eyebrow tattooing has contraindications. These include insulin-dependent diabetes, viral illnesses, epilepsy, AIDS, nervous disorders and feeling generally unwell. During pregnancy and breastfeeding, the tattoo can be done provided no anesthetic is used. Menstruation is not a contraindication.</li>\r\n<li>When choosing a micropigmentation technique, it is important to understand its pros and cons. For example, the powder technique will not hide missing natural hairs, unlike the hair-stroke technique, whose main purpose is to make brows fuller by drawing in extra hairs. On the other hand, the hair-stroke technique won\'t give the same natural look as powder brows. When choosing a method, consult your artist and look through permanent makeup photos yourself to decide what suits you best.</li>\r\n<li>No special skin care is required. We don\'t recommend applying ointments, creams or special products to speed up regeneration and healing. We always suggest letting your skin heal on its own – that is the right way. The only product you can use to disinfect the still-delicate skin is chlorhexidine or an equivalent.</li>\r\n</ul>\r\n<p>It\'s no wonder eyebrow permanent makeup is so popular all over the world. It is one of the simplest and most accessible ways to bring out your facial features while keeping a natural look. Don\'t settle for alternatives! If you want gorgeous brows that keep their look all the time, an eyebrow tattoo is the best solution.<br />Next, the artist begins the procedure. After the first stage, an anesthetic is applied to reduce pain and redness. The work continues until the perfect result is achieved. At the end of the session, the artist will give you aftercare advice and book your touch-up.</p>\r\n<p>The touch-up is considered a necessary stage of eyebrow tattooing. It helps fix any flaws that may appear as the skin recovers; the color can be intensified and, if needed, the brow shape can be refined (for example, made slightly longer or wider). Besides delivering excellent results, the touch-up extends the effect of the tattoo, so you can enjoy your affordable eyebrow tattoo for at least 1 year. The best time for a touch-up is 30–40 days after the first session.</p>\r\n<p> </p>'),
  (70, 1002, 'seo-img-1.jpg'),
  (156, 1002, '[[$table-three-col-without-top-bl7]]'),
  (275, 1002, '400-600 RON'),
  (302, 1002, '5'),
  (303, 1002, '5');
