INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1052, 'document', 'text/html', 'Microblading brows in Bucharest', 'Microblading brows in Bucharest | LBar', 'Microblading brows in Bucharest at LBar Studio ➝ Artists with 5+ years of experience ✔ Affordable prices ✎ We guarantee excellent results and a natural look', 'microblading', '', 1, 0, 0, 1002, 0, '', '', 1, 8, 2, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Microblading brows', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'microblading', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (22, 1052, 'microcatro-min.jpg'),
  (24, 1052, 'foto1-min.jpg'),
  (26, 1052, '3 reasons to choose microblading'),
  (27, 1052, 'Convenient'),
  (30, 1052, 'Perfectly groomed brows without pencil, eyeshadow or setting gel'),
  (31, 1052, 'Photo gallery – microblading before and after the procedure'),
  (32, 1052, 'Microblading brows prices in Bucharest at Studio LBar'),
  (34, 1052, 'Microblading brows reviews from our clients'),
  (35, 1052, 'Microblading brows'),
  (37, 1052, '[{\"MIGX_id\":\"1\",\"questions-title\":\"What makes the microblading technique different?\",\"questions-text\":\"<p>Microblading differs significantly from other permanent makeup techniques. Instead of a tattoo machine, the procedure uses a manual tool \\u2013 a small pen fitted with a microblade that makes fine, hair-like incisions in the skin. Pigment is then introduced into these incisions. The result is brows with ideal volume, color and density.<\\/p>\"},{\"MIGX_id\":\"2\",\"questions-title\":\"Is microblading painful?\",\"questions-text\":\"<p>No. The procedure is painless thanks to an anesthetic, which is used both before and during the procedure. You don\\u2019t need to worry about pain \\u2013 we guarantee you won\\u2019t feel any.<\\/p>\"},{\"MIGX_id\":\"3\",\"questions-title\":\"How long does eyebrow micropigmentation last?\",\"questions-text\":\"<p>It depends on your skin type and age \\u2013 on average, 1.5\\u20132 years. Microblading is not recommended for women with oily skin, because of the risk of the pigment blurring when it mixes with the skin\\u2019s oils.<\\/p>\"},{\"MIGX_id\":\"4\",\"questions-title\":\"Can I have microblading during pregnancy?\",\"questions-text\":\"<p>The procedure is contraindicated for pregnant and breastfeeding women.<\\/p>\"}]'),
  (38, 1052, 'Microblading brows in Bucharest by LBar'),
  (39, 1052, 'Brows with a stunning effect and the most natural look possible'),
  (41, 1052, '<p>The ideal brow shape and thickness<br />Natural shades matched to your individual coloring<br />A completely painless and safe procedure</p>'),
  (45, 1052, 'Microblading for femininity and natural beauty'),
  (46, 1052, '<p>Eyebrow microblading is considered one of the best-known techniques. And no wonder, since this micropigmentation can solve a number of key concerns related to both your appearance and your natural beauty. With microblading, brows become wider, thicker, longer, fuller and more defined. An eyebrow tattoo can partially reshape the brows where hairs have fallen out, or recreate them completely from scratch if, for whatever reason, the hairs are missing. Eyebrow micropigmentation will also camouflage scars, acne marks, freckles and other flaws that bother you. And all of this in an hour and a half! You won’t feel any discomfort either: microblading is painless thanks to the anesthetic and the professionalism of the artists at our LBar studio. So put away the makeup, simplify your life and choose an eyebrow tattoo.</p>'),
  (51, 1052, 'Beautiful'),
  (52, 1052, 'The hair strokes look natural and lie exactly the way you want'),
  (53, 1052, 'Effective'),
  (54, 1052, 'The tattoo hides every imperfection, so you feel confident and attractive'),
  (64, 1052, '[{\"MIGX_id\":\"1\",\"col-1\":\"Microblading brows\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"2\",\"col-1\":\"Touch-up\",\"col-2\":\"1 hour\",\"col-3\":\"\",\"col-4\":\"400 RON\"},{\"MIGX_id\":\"3\",\"col-1\":\"Correction of another artist\'s work\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"100% of the first session price\"},{\"MIGX_id\":\"5\",\"col-1\":\"Refresh within 1 year\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"80% of the original price\"}]'),
  (65, 1052, 'Answers to frequently asked questions about microblading'),
  (66, 1052, '/en/portfolio'),
  (67, 1052, 'Why do your brows every day when you can have microblading?'),
  (68, 1052, '<p>You might think that using makeup every day is a much quicker and cheaper solution. But if you add up how much money, time and effort goes into daily makeup over the 1.5–2 years that microblading lasts, you will realize that an eyebrow tattoo is far more convenient in every respect. Imagine waking up in the morning and no longer having to fill in your brows and try to shape them. You won’t need to check them in the mirror throughout the day. With affordable eyebrow micropigmentation, you can always be sure your brows look exactly the way you want: groomed and gorgeous. You won’t even need to tint or brush them. They will look perfect!</p>'),
  (69, 1052, '<h2>Microblading benefits</h2>\r\n<p>Beyond the aesthetic appeal, eyebrow micropigmentation solves a number of problems. First of all, it may be the best option if your natural brows are sparse, have partly fallen out or are missing altogether. In this case, microblading can visually create brows with the length, width, density and color tailored to you. The technique can also be an excellent choice if you:</p>\r\n<ul>\r\n<li>need to cover imperfections in the brow area, such as scars, pigmentation spots or freckles. Microblading lets you visually hide all of these flaws;</li>\r\n<li>need to correct the shape or thickness of your brows. In this case, the tattoo will visually hide asymmetry and make the brows thicker, longer, darker or more vivid;</li>\r\n<li>want to feel comfortable. Brows play an important role in your appearance, so they should always be in perfect shape. Beautiful, well-groomed brows make the whole face look well-groomed too. They also boost your self-confidence.</li>\r\n</ul>\r\n<h3>Features of the microblading technique</h3>\r\n<p>There are two microblading techniques for drawing in brows: Eastern and European. The European technique is used less often and looks less natural, because all the hairs are drawn with the same length, thickness, color and direction. Artists most often recommend it when only part of the brow needs to be drawn in. The Eastern technique, on the other hand, is more accessible and more widely used, because the hairs are drawn to fully imitate natural hair, with varying thickness, length, direction and even shade. With this technique, brows that are missing can be created from scratch and brought as close as possible to a natural look. It is worth noting that no matter how skilled and experienced the artist is, microblading cannot create completely natural brows. Visually, it will be clear that the hairs are not real. There will also be visible gaps between the strokes, showing that they are artificial. In such cases, artists often combine two techniques: microblading and the powder effect. The first creates the “structure”, while the second adds a tinted base layer that fills in those gaps. As a result, the brows look harmonious and as natural as possible. Microblading does not cover an old tattoo. The old tattoo will remain fully visible, however dense the hair strokes are. This is due to the difference in shade between the old tattoo and the new micropigmentation, as well as the spaces between the strokes, which leave small gaps.</p>\r\n<h3>Contraindications</h3>\r\n<p>Microblading has a number of contraindications. The most obvious include diabetes (type 1 and type 2), epilepsy, skin conditions and inflammation, pregnancy and breastfeeding. Microblading can be done during your period. It is important to be in good health for the procedure. If you are feeling unwell, it is best to reschedule for another day.</p>\r\n<h3>Preparing for microblading and aftercare</h3>\r\n<p>Avoid excessive alcohol and caffeine before the procedure. Ideally, don’t drink any coffee at all that day. Avoid taking anticoagulants the day before your session. Where possible, it is also advisable to pause hormonal medication for a while. Don’t wear any brow makeup when you come in for the procedure.<br />It is important to pay special attention to your skin after microblading. This technique is a specific procedure that involves injuring the skin with a fine blade, and the skin needs care in order to heal. Right after the session, your artist should recommend products to help the skin heal and recover. Just in case, keep chlorhexidine on hand to disinfect the skin and remove any lymph fluid that seeps out.</p>\r\n<h3>Stages of the microblading procedure</h3>\r\n<p>The microblading procedure begins with drawing a sketch. The artist will follow it exactly while creating your makeup. The sketch also lets you see in advance how your brows will look after micropigmentation. Once the sketch is approved, the artist applies an anesthetic. It takes about 15–20 minutes to take effect, and then the artist gets to work. During the procedure, an additional anesthetic is applied to reduce pain, redness and possible skin inflammation. At the end of the session, the artist will give you aftercare advice and book your touch-up appointment.<br />A touch-up is essential with microblading. As the skin regenerates, some of the pigment is shed and the hair strokes become lighter. The touch-up restores the strokes’ intensity and can also adjust their shade, length or thickness. It is best done as soon as the skin has healed and recovered, usually one month after your first visit to the studio.</p>\r\n<p>Microblading is highly valued by women for good reason. One short procedure transforms the whole look of the face. And when a woman feels beautiful and confident, every day is a true joy.</p>'),
  (70, 1052, 'seo-img-1.jpg'),
  (77, 1052, '/chto-takoe-microblading-brovey'),
  (79, 1052, 'microlbar2-min.jpg'),
  (83, 1052, '/uhod-za-brovyami-posle-microbladinga'),
  (85, 1052, 'microlbar7-min.jpg'),
  (89, 1052, '/microblading-i-drugie-tehniki-permanentnogo-makiyazha-brovey'),
  (91, 1052, 'microlbar9-min.jpg'),
  (128, 1052, 'Professional materials <br/>and supplies'),
  (129, 1052, 'We use only tested hypoallergenic pigments and professional equipment'),
  (130, 1052, 'Maximum <br/>long-lasting effect'),
  (131, 1052, 'Gorgeous, natural-looking brows that last up to 1.5–2 years, with no need for daily makeup'),
  (156, 1052, '[[$table-three-col-without-top-bl7]]'),
  (275, 1052, '400-600 RON');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1053, 'document', 'text/html', 'Hair-stroke eyebrow micropigmentation in Bucharest', 'Hair-stroke eyebrow micropigmentation in Bucharest, prices | LBar', 'Get hair-stroke eyebrow micropigmentation in Bucharest at Studio LBar ⚡ Artists with 5+ years of experience ✔ Affordable prices ✎ Excellent, natural results', 'hair-stroke-brows', '', 1, 0, 0, 1002, 0, '', '', 1, 8, 1, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Hair-stroke eyebrow micropigmentation', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'hair-stroke-brows', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (22, 1053, 'fircufircatro-min.jpg'),
  (24, 1053, 'original_13-min.jpg'),
  (26, 1053, 'Choose hair-stroke eyebrow micropigmentation if:'),
  (27, 1053, 'Very sparse brows'),
  (30, 1053, 'Drawn-in hair strokes visually add volume and density to your brows'),
  (31, 1053, 'Photo gallery – hair-stroke eyebrow micropigmentation before and after the procedure'),
  (32, 1053, 'Hair-stroke eyebrow tattoo prices in Bucharest at Studio LBar'),
  (34, 1053, 'Hair-stroke eyebrow micropigmentation reviews from our clients'),
  (35, 1053, 'Hair-stroke eyebrow micropigmentation'),
  (37, 1053, '[{\"MIGX_id\":\"1\",\"questions-title\":\"What makes the hair-stroke eyebrow tattoo technique special?\",\"questions-text\":\"<p>What sets the hair-stroke technique apart is that each hair stroke can be drawn by hand, creating volume, width and length to suit your preferences and features.<\\/p>\"},{\"MIGX_id\":\"2\",\"questions-title\":\"Is hair-stroke eyebrow micropigmentation painful?\",\"questions-text\":\"<p>No. The procedure is painless thanks to an anesthetic that reduces not only pain but also redness and skin inflammation.<\\/p>\"},{\"MIGX_id\":\"3\",\"questions-title\":\"What is the difference between hair-stroke brows and microblading?\",\"questions-text\":\"<p>In terms of the final result, the techniques are identical. The only difference is the equipment used during the procedure. Microblading uses a manual tool \\u2013 a small pen fitted with a microblade that makes an incision in the skin, into which the pigment is placed. In hair-stroke tattooing, the strokes are drawn with a classic semi-permanent makeup machine. The hair-stroke technique is safer and more reliable than microblading.<\\/p>\"},{\"MIGX_id\":\"4\",\"questions-title\":\"Can I have hair-stroke eyebrow micropigmentation during pregnancy?\",\"questions-text\":\"<p>No. Hair-stroke eyebrow micropigmentation is contraindicated during pregnancy and breastfeeding, because an anesthetic has to be applied during the procedure.<\\/p>\"}]'),
  (38, 1053, 'Hair-stroke eyebrow micropigmentation in Bucharest'),
  (39, 1053, 'Brows exactly the way you wanted them, true to the technique’s standards and the latest permanent makeup trends'),
  (41, 1053, '<p>Defined lines and edges with a natural look<br />Shade and shape chosen to suit your features<br />A safe, sterile procedure, guaranteed</p>'),
  (45, 1053, 'Natural beauty and self-confidence with hair-stroke eyebrow tattooing'),
  (46, 1053, '<p>Hair-stroke eyebrow pigmentation is a simple way to restore the shape and density of your brows. It is an ideal technique for sparse hairs, chaotic and uneven growth, or hair loss caused by illness. The main difference between microblading and other techniques is that it fully imitates the growth of natural brows. Here, the artist draws each hair stroke by hand, individually choosing its length, thickness, direction and shade. The result looks quite natural, the brow shape is correct, and the density is exactly what you need. You no longer have to worry about missing hairs in your brow area. The hair-stroke technique will restore volume quickly and safely.</p>'),
  (51, 1053, 'Missing your brows'),
  (52, 1053, 'A hair-stroke tattoo can recreate your brows, even if they are partly or completely missing'),
  (53, 1053, 'Want beautiful brows'),
  (54, 1053, 'The right shape, optimal thickness and width – hair-stroke eyebrow pigmentation suits you 100%'),
  (64, 1053, '[{\"MIGX_id\":\"1\",\"col-1\":\"Hair-stroke eyebrow micropigmentation\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"2\",\"col-1\":\"Hybrid technique\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"3\",\"col-1\":\"Correction of another artist\'s work\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"100% of the first session price\"},{\"MIGX_id\":\"5\",\"col-1\":\"Refresh within 1 year\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"80% of the original price\"},{\"MIGX_id\":\"6\",\"col-1\":\"Touch-up\",\"col-2\":\"1 hour\",\"col-3\":\"\",\"col-4\":\"400 RON\"}]'),
  (65, 1053, 'Answers to questions about hair-stroke eyebrow tattooing'),
  (66, 1053, '/en/portfolio'),
  (67, 1053, 'Hair-stroke eyebrow permanent makeup for a flawless look'),
  (68, 1053, '<p>Hair-stroke eyebrow permanent makeup has no alternative. It is a unique technique performed with a modern micropigmentation machine that lets you completely reshape your brows so they look as close to natural as possible. Admittedly, on close inspection you can tell the brows have been tattooed, which is why they can’t be considered completely natural. Still, when brows need more density, the hair-stroke technique is unrivaled. There are also several affordable eyebrow tattooing techniques, so you can choose the one that gives the best result and suits you perfectly.</p>'),
  (69, 1053, '<h2>What you should know about hair-stroke eyebrow tattooing</h2>\r\n<p>Let’s take a closer look at this method.</p>\r\n<h3>Hair-stroke eyebrow permanent makeup techniques</h3>\r\n<p>There are two types: Eastern and European. The European technique involves drawing hair strokes of the same length and thickness, following the direction of growth. This option is used less often, but it is recommended when only part of the brow arch needs to be reshaped. The Eastern technique, by contrast, involves drawing strokes of different lengths, thicknesses and growth directions, and even in different shades. This makes the brows look more natural and effortless. It is used when the brows need to be reshaped completely.</p>\r\n<h3>Benefits of the hair-stroke technique</h3>\r\n<p>If your brows are sparse or very light and you don’t want to fill them in all the time, choose the hair-stroke technique. It will:</p>\r\n<ul>\r\n<li>make the shape look brighter and more expressive. The arch will look great and be neatly defined, and the brows will have a natural shade without looking overdone;</li>\r\n<li>hide imperfections. Scars, for example, will visually disappear completely. This technique may be the best option when certain flaws need to be concealed;</li>\r\n<li>make you feel confident. You will no longer need to tint your brows, carry a makeup bag or do your makeup every morning.</li>\r\n</ul>\r\n<p>Your brows will always look beautiful after the beach, the pool or a bath.<br />It is worth stressing that this technique is rarely used on its own. Most often it is combined with powder brows micropigmentation. This way, you can achieve the most natural look possible.</p>\r\n<h3>Stages of the hair-stroke eyebrow micropigmentation procedure</h3>\r\n<p>Hair-stroke eyebrow permanent makeup starts with choosing the pigment, after which the sketch is drawn. This is an important step: the experienced artist draws each hair stroke, creating an even brow design. You need to see how your brows will look in the end and decide whether the design suits you. Next, the artist performs the tattoo. At first, no anesthetic is used. It isn’t needed, since the skin is not yet injured and the first stage is painless. An additional anesthetic is then applied, and the process is repeated until the desired effect is achieved. At the end of the session, the artist will give you aftercare advice and book your touch-up appointment.</p>\r\n<h3>A touch-up is a must!</h3>\r\n<p>If you want the result to last longer, don’t skip the touch-up after your hair-stroke eyebrow tattoo. It enriches the strokes with color and, if needed, lets the artist redraw areas where the strokes have lost their shape or color. It is best to have the touch-up 28–30 days after your first session. By then, the skin is considered fully regenerated and ready for pigment again.</p>\r\n<h3>How long it lasts</h3>\r\n<p>How long a hair-stroke tattoo lasts varies from person to person – on average, 1.5–2 years. The key factors are skin type, age and lifestyle. People with oily skin should have touch-ups more often, as the effect may start to fade as early as 6–8 months after the touch-up. In older people or those with dry skin, the effect lasts longer.</p>\r\n<h3>Contraindications</h3>\r\n<p>The main contraindications for the hair-stroke technique include insulin-dependent diabetes, HIV, AIDS, epilepsy, skin inflammation in the brow area, pregnancy and breastfeeding. The procedure is not recommended if you are feeling unwell or have a viral illness, a high temperature or high blood pressure. Your period is not a contraindication.</p>\r\n<h2>Have you decided to get a hair-stroke eyebrow tattoo?</h2>\r\n<p>Wonderful! The artists at our LBar studio in Bucharest will be happy to help. We guarantee a procedure that is completely safe in every possible way: we use only single-use disposables, high-quality pigments, professional equipment and triple sterilization of reusable tools. Sparse brows, or brows that are partly or completely missing, are no longer a problem. Simply choose affordable hair-stroke eyebrow tattooing and enjoy your newfound confidence.</p>'),
  (70, 1053, 'uverennost.jpg'),
  (128, 1053, 'Professional materials <br/>and supplies'),
  (129, 1053, 'We use only tested hypoallergenic pigments and professional equipment'),
  (130, 1053, 'Maximum <br/>long-lasting effect'),
  (131, 1053, 'Gorgeous, natural-looking brows that last up to 1.5–2 years, with no need for daily makeup'),
  (156, 1053, '[[$table-three-col-without-top-bl7]]'),
  (275, 1053, '600-600 RON');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1054, 'document', 'text/html', '3D/6D eyebrow tattoo', '≋ 3D/6D EYEBROW TATTOO ≋ in Bucharest ‣ PERMANENT MAKEUP | LBar', 'Get a 3D/6D eyebrow tattoo in Bucharest⭐️We create a flawless look. Affordable prices, custom shape⚡️Lasts up to 2 years. 100% natural look ⚡️Top artists', '3d-6d-eyebrow-tattoo', '', 1, 0, 0, 1002, 0, '', '', 1, 8, 2, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, '3D/6D eyebrow tattoo', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, '3d-6d-eyebrow-tattoo', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (22, 1054, '3dcatro-min.jpg'),
  (24, 1054, 'original_13-min.jpg'),
  (26, 1054, '3D/6D semi-permanent eyebrow makeup – the best option if:'),
  (27, 1054, 'Your brows are light and sparse'),
  (30, 1054, 'A 3D tattoo helps restore brow volume and gives a natural shade'),
  (31, 1054, 'Photo gallery – 3D/6D eyebrow permanent makeup before and after the procedure'),
  (32, 1054, '3D/6D eyebrow tattoo prices in Bucharest at Studio LBar'),
  (34, 1054, '3D/6D eyebrow micropigmentation reviews from our clients'),
  (35, 1054, '3D/6D eyebrow tattoo'),
  (37, 1054, '[{\"MIGX_id\":\"1\",\"questions-title\":\"What makes the 3D\\/6D tattoo technique different from other techniques?\",\"questions-text\":\"<p>The 3D tattoo technique differs from the others in that it combines two techniques at once: hair-stroke and powder. Besides combining techniques, several shades can be used at the same time during the procedure to lighten, darken and highlight the color of the hair strokes. The method is used to achieve brows that look as natural as possible.<\\/p>\"},{\"MIGX_id\":\"2\",\"questions-title\":\"Who is the 3D microblading brows technique suitable for?\",\"questions-text\":\"<p>There are absolutely no restrictions or special recommendations. A 3D tattoo suits any woman who wants gorgeous brows. This technique is ideal for people whose brows are partially or completely missing.<\\/p>\"},{\"MIGX_id\":\"3\",\"questions-title\":\"How long does a 3D\\/6D tattoo last?\",\"questions-text\":\"<p>Up to 2 years. How long the effect lasts depends on your skin type and age, your lifestyle and other individual factors. For some people, the tattoo can last up to 2.5\\u20133 years, while for others it lasts up to 1\\u20131.5 years.<\\/p>\"},{\"MIGX_id\":\"4\",\"questions-title\":\"Is 3D eyebrow micropigmentation painful?\",\"questions-text\":\"<p>The procedure is painless thanks to a numbing cream. It reduces pain, redness and skin inflammation.<\\/p>\"}]'),
  (38, 1054, '3D/6D eyebrow tattoo in Bucharest by LBar'),
  (39, 1054, 'Natural, beautiful brows created with a modern, professional technique'),
  (41, 1054, '<p>The perfect brow shape and shade<br />Painless and completely sterile</p>'),
  (45, 1054, '3D/6D microblading brows for elegant women who appreciate beauty'),
  (46, 1054, '<p>3D/6D eyebrow permanent makeup is an unprecedented concept in the beauty industry. The technique involves the artist\'s meticulous work in selecting shades, the combination of two techniques, a unique application method and an amazingly natural, impressive result. Just imagine: beautiful brows with the ideal length, width and shade that blend perfectly with your features, highlighting your eyes and face for a well-groomed, fresh look. What\'s more, the 3D/6D eyebrow tattoo technique can help hide noticeable flaws that used to make you feel self-conscious. As a result, you feel more confident in any situation, because your brows stay perfect whatever you\'re doing.</p>'),
  (51, 1054, 'Missing your brows'),
  (52, 1054, 'Combining the hair-stroke and powder techniques visually restores your brows, even if they are missing'),
  (53, 1054, 'Want elegant makeup'),
  (54, 1054, '3D and 6D brows last up to 2 years and help preserve and enhance your natural beauty'),
  (64, 1054, '[{\"MIGX_id\":\"1\",\"col-1\":\"3D\\/6D eyebrow tattoo\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"2\",\"col-1\":\"Touch-up\",\"col-2\":\"1 hour\",\"col-3\":\"\",\"col-4\":\"400 RON\"},{\"MIGX_id\":\"4\",\"col-1\":\"Correction of another artist\'s work\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"100% of the first session price\"},{\"MIGX_id\":\"5\",\"col-1\":\"Refresh within 1 year\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"80% of the original price\"}]'),
  (65, 1054, 'Answers to questions about the 3D/6D eyebrow tattoo'),
  (66, 1054, '/en/portfolio'),
  (67, 1054, 'Beautiful brows made simple and affordable. Get a 3D/6D eyebrow tattoo'),
  (68, 1054, '<p>Getting natural, beautiful brows is easier than you think. All you need to do is book a 3D or 6D eyebrow micropigmentation session at an affordable price, and then decide which technique to choose. The result will be excellent: your brows will look well-groomed, and you\'ll look stunning. What\'s more, eyebrow permanent makeup can hide various imperfections that bother you, such as a small scar or acne marks. That\'s why the 3D eyebrow tattoo is considered one of the most effective ways to visually restore the brow arch when the hairs are partially or completely missing.</p>'),
  (69, 1054, '<h2>What is a 3D eyebrow tattoo and why is it called that?</h2>\r\n<p>The 3D technique gets its name from the final effect achieved after the procedure. By combining two techniques and several pigment shades, permanent makeup can fully recreate the brows and make them look as natural as possible. The artist can match or blend pigment shades from the darkest to the lightest to create a natural-looking final color. In the hair-stroke technique, the artist draws the hairs by hand. They can vary in length, thickness, growth direction and even color to create a natural effect, just like real hair. As soon as the brows are shaped to the desired thickness and length, the powder-effect eyebrow micropigmentation technique is used to create a base layer beneath the hair strokes. This way, we guarantee that the strokes won\'t look patchy and the whole look will be harmonious. <br />The 6D eyebrow tattoo technique is similar to 3D, but it gets its name from the fact that a larger number of shades can be used.</p>\r\n<h2>Benefits of the 3D/6D eyebrow tattoo technique</h2>\r\n<p>The main advantage of the technique is that it can camouflage completely or partially missing brows. This matters in cases of congenital anomalies or past illnesses, or when someone has very sparse, very light hair. 3D and 6D eyebrow micropigmentation can also help you:<br />hide any imperfections in the brow area, including deep scars – combining the two techniques covers everything that needs covering;<br />transform your look and feel more confident, thanks to well-groomed brows that always look neat;<br />save a considerable amount of personal time that used to go into daily makeup.</p>\r\n<h2>3D/6D brows: before and after the procedure</h2>\r\n<p>Although you don\'t need to study every detail of how to prepare for the procedure, you shouldn\'t ignore this step completely either. It\'s best not to pluck or tint your brows for a week before the procedure, and to avoid caffeinated drinks and alcohol the day before. Also, don\'t overdo medications, especially blood thinners. These should not be taken for 2 days before the procedure, and the same goes for hormonal medications. However, these suggestions don\'t apply after the procedure. It\'s important to pay even closer attention to the period after the procedure and follow your artist\'s recommendations:</p>\r\n<ul>\r\n<li>Don\'t apply healing ointments. Let the skin heal on its own – it\'s better that way. To prevent infection, chlorhexidine or a similar product is recommended.</li>\r\n<li>Don\'t steam your skin in any way. This includes saunas, sitting or lying in a hot bath for a long time, washing your face with hot water and going to the pool. Wash your face with lukewarm water and a gentle cleanser.</li>\r\n<li>Avoid sunlight. Cover the tattooed area with a hat, a cap or sunglasses. You can apply SPF40+ sunscreen.</li>\r\n<li>Don\'t touch, scratch or, under any circumstances, pick off flaking skin. Doing so will damage the tattoo, and you may re-injure the skin and cause suppuration or bleeding. This will prolong the healing of your 6D/3D permanent makeup and affect how your brows look.</li>\r\n<li>Have the touch-up one month after the first session.</li>\r\n</ul>\r\n<h3>Is a touch-up mandatory after a 3D/6D eyebrow tattoo?</h3>\r\n<p>The touch-up is considered the second, follow-up stage of the procedure, so it shouldn\'t be skipped. It helps fix any flaws that may appear while the skin regenerates and also lets you slightly adjust the look of your brows if you wish. For example, the brows can be made a little wider, thicker or darker. In addition, re-introducing pigment into the skin makes your eyebrow permanent makeup stay visible for longer.</p>\r\n<h2>Stages of the 3D eyebrow permanent makeup procedure</h2>\r\n<p>The procedure includes the following stages:</p>\r\n<ol>\r\n<li>Creating the sketch. The artist draws the hairs by hand so that the shape, length and density of the brow are clearly visible. The sketch is useful both for you and for the artist, who will follow it exclusively while doing the makeup. That\'s why it\'s important to reach a mutual agreement and choose the perfect design for your future brows.</li>\r\n<li>Performing the procedure. Step by step, the artist draws each hair, giving it a natural look. Once the hair-stroke tattoo is finished, the artist moves on to the second technique – powder micropigmentation, which completes the final look. An anesthetic is used during tattooing. It reduces pain and skin redness.</li>\r\n<li>At the end of the procedure, the artist will give you detailed skin care advice and book you in for a touch-up.</li>\r\n</ol>\r\n<h3>Recommendations and contraindications</h3>\r\n<p>This technique is ideal for women with sparse or blonde brows, or with partially or completely missing brows. However, that\'s not a limit: any woman who wants to look well-groomed and feminine can benefit from 3D permanent makeup. Before booking the procedure, though, keep in mind that it has some contraindications. These include:</p>\r\n<ul>\r\n<li>pregnancy and breastfeeding, because the anesthetic used contains lidocaine;</li>\r\n<li>type 1 or type 2 diabetes;</li>\r\n<li>epilepsy;</li>\r\n<li>nervous system disorders;</li>\r\n<li>viral illnesses;</li>\r\n<li>HIV, AIDS;</li>\r\n<li>inflammation of the skin in the brow area;</li>\r\n<li>cuts or unhealed wounds.</li>\r\n</ul>\r\n<p>Relative contraindications include feeling unwell, fever or high blood pressure – in these cases, it\'s best to postpone the procedure and let your artist know in advance.<br />3D/6D eyebrow micropigmentation pays off in every way. Besides the obvious time savings on daily makeup, it gives you an attractive look and self-confidence. After all, beautiful brows instantly transform your appearance and make your face more expressive. Book an appointment, and we, the artists at Studio LBar in Bucharest, will be delighted to help you look even more beautiful!</p>'),
  (70, 1054, 'uverennost.jpg'),
  (128, 1054, 'Professional materials <br/>and supplies'),
  (129, 1054, 'We use only tested hypoallergenic pigments and professional equipment'),
  (130, 1054, 'Maximum <br/>long-lasting effect'),
  (131, 1054, 'Gorgeous, natural-looking brows that last up to 1.5–2 years, with no need for daily makeup'),
  (156, 1054, '[[$table-three-col-without-top-bl7]]'),
  (275, 1054, '400-600 RON');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1080, 'document', 'text/html', 'LBar permanent makeup studio services', 'LBar permanent makeup studio services in Bucharest', 'Services of our permanent makeup studio in Bucharest. Artists with 3+ years of experience ⭐ Affordable prices with a custom shape for you. 100% positive reviews', 'services', '', 1, 0, 0, 0, 1, '', '', 1, 22, 2, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Services', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'services', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (48, 1080, '1002,1167,1162'),
  (49, 1080, 'Create a natural, elegant look and highlight your individuality. Choose the service that will make you truly happy.'),
  (50, 1080, 'LBar cosmetic tattoo studio services'),
  (67, 1080, 'LBar permanent makeup studio services'),
  (68, 1080, '<p>Studio LBar offers eyebrow, lip and eyelid micropigmentation in the best-known and most popular techniques. Creating a natural, harmonious look is what sets us apart.</p>\r\n<ul>\r\n<li>We know that every client has their own idea of beauty. That\'s why we offer micropigmentation in a variety of techniques. We offer:</li>\r\n<li>Eyebrow micropigmentation: powder, hair-stroke, microblading, ombré and 3D/6D techniques.</li>\r\n<li>Eye micropigmentation: lower/upper lash line, classic eyeliner, eyeliner with shading.</li>\r\n<li>Lip micropigmentation in aquarelle and ombré techniques.</li>\r\n<li>Beauty mark tattoo.</li>\r\n</ul>\r\n<p>We also offer the following additional services:</p>\r\n<ul>\r\n<li>Covering old tattoos, including unsuccessful work done by another artist. We handle even the most difficult cases, when the pigment has an unpleasant shade and an unattractive, uneven shape.</li>\r\n<li>Correction of semi-permanent makeup done by one of our artists or by another artist.</li>\r\n<li>Removal of tattoos and semi-permanent makeup with modern, high-performance equipment, with up to 98% guaranteed removal.</li>\r\n</ul>\r\n<p>Whichever service you choose, we guarantee quality and sterile conditions. Reusable equipment goes through three-stage sterilization in line with all standards and requirements. Consumables are single-use and disposed of immediately after use. Single-use needles are opened in front of the client.</p>\r\n<p>We stand for natural results and quality. Want a result that exceeds your expectations? Come to Lbar. Our micropigmentation services are at your disposal.</p>');
