INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1102, 'document', 'text/html', 'About Lbar micropigmentation studio', 'About Lbar semi-permanent makeup studio by Ksenia Kobilianskaia', 'Detailed information about LBar micropigmentation studio by Ksenia Kobilianskaia in Bucharest (Romania). Our history and our journey', 'about-us', '', 1, 0, 0, 0, 1, '', '', 1, 3, 7, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'About us', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'about-us', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (93, 1102, '<p>LBar micropigmentation studio is a chain of luxury studios with thousands of reviews and recommendations. Over more than 5 years of continuous work, we have become one of the most highly rated and popular cosmetic tattoo studios in Kyiv and Ukraine, and every day, with every procedure we perform, we work hard to live up to that reputation.</p>\r\n<p>Our permanent makeup studio successfully provides its services in Warsaw and Bucharest, while continuing to operate in Kyiv. Over this time, our artists have performed 10,000+ micropigmentation procedures in a variety of techniques and on different areas. We keep improving, providing every procedure with premium supplies, strictly following sanitary standards and carefully looking after the safety of both client and artist.<br />Today, our permanent makeup studios are spacious, modern and comfortable. Our studio offers a wide range of micropigmentation services, old tattoo removal and professional training courses. The Lbar Tattoo School has trained more than 400 successful artists who now work all over the world.<br />We work for you, for your beauty and self-confidence. We promise it will be gorgeous!</p>\r\n<p>See what our clients say about us and discover our additional offers.</p>\r\n<p><a href=\"/en/reviews\" target=\"_blank\">Reviews</a><br /><a href=\"/en/careers\" target=\"_blank\">Vacancies</a></p>');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1105, 'document', 'text/html', 'Careers at Studio LBar', 'Job openings at LBar micropigmentation studio in Bucharest', 'Job openings at LBar micropigmentation studio in Bucharest: permanent makeup artist, eyelash extension artist and manicurist (nail technician)', 'careers', '', 1, 0, 0, 1102, 0, '', '', 1, 3, 3, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Careers', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'careers', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (93, 1105, '<p>We are actively looking for talented, experienced specialists who want to work in a modern studio, in good conditions and for a competitive salary.</p>\r\n<p><strong>Permanent makeup artist</strong></p>\r\n<p>We have an opening for a permanent makeup artist. Requirements:</p>\r\n<ul>\r\n<li>At least 1 year of experience or a minimum of 400 procedures performed.</li>\r\n<li>A personal portfolio so we can assess the quality of your work.</li>\r\n<li>Knowledge of permanent makeup techniques: hair-stroke brows, powder brows micropigmentation, aquarelle lips, lower/upper eyelid tattoo, eyeliner.</li>\r\n<li>Ability to work quickly and to a high standard while following safety rules.</li>\r\n<li>Resilience under stress.</li>\r\n<li>Ability to find the right approach to every client.</li>\r\n</ul>\r\n<p>To inquire about this position, send us photos of your work on Instagram.</p>\r\n<p><strong>Eyelash extension artist</strong></p>\r\n<p>We have an opening for an eyelash extension artist.</p>\r\n<p>Requirements:</p>\r\n<ul>\r\n<li>Knowledge of 2D, 3D, 5D, 6D and Hollywood eyelash extension techniques.</li>\r\n<li>At least 1 year of experience or more than 400 completed sets.</li>\r\n<li>A personal portfolio showcasing your work.</li>\r\n<li>Ability to handle a heavy workload.</li>\r\n</ul>\r\n<p>To inquire about this position, send us photos of your work on Instagram.</p>\r\n<p><strong>Manicurist (nail technician)</strong></p>\r\n<p>Our studio is looking for an experienced manicurist.</p>\r\n<p>Requirements:</p>\r\n<ul>\r\n<li>Ability to work with a variety of manicure techniques.</li>\r\n<li>Ability to use different materials and techniques for coating natural nails, as well as for nail extensions and strengthening.</li>\r\n<li>A personal portfolio showcasing your work.</li>\r\n<li>At least 1 year of experience or more than 400 completed jobs.</li>\r\n</ul>\r\n<p>To inquire about this position, send us photos of your work on Instagram.</p>\r\n<p> </p>');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1119, 'document', 'text/html', 'Micropigmentation touch-up in Bucharest', 'Micropigmentation touch-up Bucharest ᐈ Brows, lips & eyes | LBar', 'Brow, lip & eye micropigmentation touch-ups in Bucharest at Studio LBar ➝ Artists with 5+ years of experience ✔ Affordable prices ✎ Natural results guaranteed', 'micropigmentation-touch-up', '', 1, 0, 0, 1080, 0, '', '', 1, 8, 12, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Touch-up', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'micropigmentation-touch-up', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (31, 1119, 'Photo gallery – eyebrow, eye and lip micropigmentation touch-ups before and after the procedure'),
  (32, 1119, 'Micropigmentation touch-up prices in Bucharest at Studio LBar'),
  (34, 1119, 'Touch-up reviews from our clients'),
  (37, 1119, '[{\"MIGX_id\":\"1\",\"questions-title\":\"Is a touch-up necessary?\",\"questions-text\":\"<p>A touch-up is recommended for all techniques and micropigmented areas. The only exception may be the eye (lash line) tattoo, because it is done with black pigment and is also less exposed to external factors that can make the pigment gradually break down and fade.<\\/p>\"},{\"MIGX_id\":\"2\",\"questions-title\":\"When is the best time for a lip micropigmentation touch-up?\",\"questions-text\":\"<p>The ideal time for a touch-up is one month after the first session. That is when the skin is considered to have recovered, so the pigment can be placed again. Note that during this period the service costs 50% of the first session price. After that, the touch-up costs 100% of the price of the technique.<\\/p>\"},{\"MIGX_id\":\"3\",\"questions-title\":\"How much does an eyebrow tattoo touch-up cost?\",\"questions-text\":\"<p>It costs 50% of the first session price if the touch-up is done 30\\u201345 days after the first procedure. After that, the touch-up costs 100% of the price of the technique.<\\/p>\"},{\"MIGX_id\":\"4\",\"questions-title\":\"How do I know if I need a touch-up?\",\"questions-text\":\"<p>A touch-up is needed if the shape or color of the tattoo needs improving, or if local imperfections need correcting. In any case, even if there is nothing to correct, the touch-up works as \\u201cprevention\\u201d to keep the effect visible for longer. That said, a touch-up is not mandatory for an eye tattoo, but it is important for powder brows micropigmentation.<\\/p>\"}]'),
  (38, 1119, 'Eyebrow, eye and lip micropigmentation touch-up in Bucharest at LBar'),
  (39, 1119, 'We add color, correct flaws, adjust the shape and give your tattoo a perfect finish'),
  (41, 1119, '<p>Every millimeter of the area perfected<br />Shade chosen individually for you</p>'),
  (45, 1119, 'Have you already booked your eyebrow, eye or lip micropigmentation touch-up?'),
  (46, 1119, '<p>Don\'t miss this opportunity. In fact, the tattoo touch-up is always considered the second mandatory and important stage of every micropigmentation procedure. Although a touch-up takes no more than 30–60 minutes, the result exceeds all expectations. The touch-up doesn\'t just finish your brow, lip or eye tattoo – it adds color, depth of shade and shape, and eliminates any imperfections that may appear while the skin regenerates. The touch-up definitely extends the effect, since the pigment is placed in the skin again during the procedure. So, thanks to the touch-up, your tattoo will last six months or even a year longer.</p>'),
  (64, 1119, '[{\"MIGX_id\":\"1\",\"col-1\":\"Eyebrow micropigmentation touch-up\",\"col-2\":\"1 hour\",\"col-3\":\"200 RON\",\"col-4\":\"300 RON\"},{\"MIGX_id\":\"2\",\"col-1\":\"Lip micropigmentation touch-up\",\"col-2\":\"1 hour\",\"col-3\":\"200 RON\",\"col-4\":\"300 RON\"},{\"MIGX_id\":\"3\",\"col-1\":\"Lash line enhancement touch-up\",\"col-2\":\"1 hour\",\"col-3\":\"200 RON\",\"col-4\":\"300 RON\"},{\"MIGX_id\":\"17\",\"col-1\":\"Refresh within 1 year\",\"col-2\":\"1 hour\",\"col-3\":\"80% of the original price\",\"col-4\":\"80% of the original price\"}]'),
  (65, 1119, 'Answers to questions about touch-ups'),
  (67, 1119, 'The importance and specifics of a tattoo touch-up'),
  (68, 1119, '<p>Many women skip the semi-permanent makeup touch-up because they find the healed result completely satisfying. But after 6 months or a year, the effect fades noticeably, which can be upsetting and may lead them to think the artist wasn\'t professional enough or used low-quality supplies. In reality, the true reason is that the touch-up was skipped. The procedure takes half the time and costs 50% of the original price, yet the benefits are three times greater.</p>'),
  (69, 1119, '<h2>Why do you need a tattoo touch-up?</h2>\r\n<p>Whatever the technique or the area of micropigmentation, a touch-up offers the following benefits:</p>\r\n<ul>\r\n<li>It corrects minor imperfections – for example, gaps, lighter patches, uneven color or missed spots: any flaws that may appear while the skin heals.</li>\r\n<li>It helps refine the shape. For example, brows can be made wider or longer, the lip contour more defined, and the eyeliner longer and more lifted at the top.</li>\r\n<li>It brings back the brightness of the shade. During the touch-up, the same shade as before can be used, or you can opt for a slightly more intense color – for example, turn light pink lips into a deep pink or get darker brows.</li>\r\n<li>It extends the effect by placing the pigment again. Thanks to the touch-up, your tattoo will last for a good long time.</li>\r\n<li>It fully completes the look chosen at the initial procedure. The tattoo takes on its final appearance, and you get to enjoy all its obvious benefits.</li>\r\n</ul>\r\n<h2>When to have a touch-up and how it is done</h2>\r\n<p>Right after the first session, the artist picks the most suitable date and books your touch-up. It is usually done 28–35 days after the initial procedure. We recommend sticking to this time frame, as it is considered the best window for a touch-up after micropigmentation.<br />When you come back to the artist for the touch-up, the procedure is no different from the first one. The only difference is the duration and the intensity of the color work. Most often, if the color doesn\'t need to change, the artist fills in only the gaps in the micropigmented area to eliminate minor imperfections. But if the entire area needs correcting, the pigment is applied over the whole area. It all depends on the individual situation and is discussed before the touch-up. The artist assesses how your semi-permanent brow, lash line or lip makeup looks and suggests the best solution, so that you ultimately get an excellent, natural result.</p>\r\n<h3>How does the skin heal after a touch-up? Does it need special care?</h3>\r\n<p>If you had your permanent makeup done at our studio, you already know how quickly and smoothly the skin heals after micropigmentation. We guarantee that healing after a touch-up is practically the same. It also matters how the tattoo is done – whether the entire micropigmented area is worked on or only part of it. Either way, during the touch-up the pigment is placed in the upper layers of the skin, so it is essentially painless, and the skin heals quickly and without complications.<br />For aftercare, the artist will recommend only chlorhexidine or an equivalent product to disinfect the skin. No special care with various ointments and healing products is needed.</p>\r\n<h2>What problems can arise if you skip the permanent makeup touch-up?</h2>\r\n<p>As a rule, during eyebrow micropigmentation – especially with the powder technique – the artist places the pigment in the upper layers of the skin. This makes it possible to see how your body absorbs the pigment and what shade it produces. Color retention can be 90–100% or as low as 20%. Before the touch-up, the experienced artist usually assesses how the tattoo looks and places the pigment again, slightly deeper. This method achieves the maximum, natural-looking aesthetic effect. So if you skip the touch-up, the small amount of pigment left in the skin after the first session means the effect will fade from view within 4–6 months.<br />In fact, the touch-up extends how long the effect lasts. Without it, you can\'t expect your semi-permanent makeup to last 1.5 to 2 years. This is especially true for people with oily skin: subcutaneous oil rejects and expels the pigment much faster, which is why another touch-up may be needed six months after the previous one.<br />A tattoo touch-up is considered an inexpensive yet very beneficial and affordable procedure. It is recommended as the essential second micropigmentation session. That way, you\'ll discover all the advantages of permanent makeup and enjoy them for longer.</p>'),
  (70, 1119, 'uverennost.jpg'),
  (128, 1119, 'Professional materials <br/>and supplies'),
  (129, 1119, 'We use only tested hypoallergenic pigments and professional equipment'),
  (130, 1119, 'Maximum <br/>long-lasting effect'),
  (131, 1119, 'A gorgeous, natural effect for up to 2 years and a perfect look'),
  (275, 1119, '400-600 RON');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1120, 'document', 'text/html', 'Permanent makeup artist Ksenia Kobilianskaia: work photos and reviews', 'Ksenia Kobilianskaia – PMU artist: bio, portfolio photos, reviews', 'Permanent makeup artist in Bucharest – Ksenia Kobilianskaia. About the artist, photos of her work and client reviews. Read and leave a review – LBar Studio', 'ksenia-kobilianskaia', '', 1, 0, 0, 1100, 0, '', '', 1, 13, 0, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Ksenia Kobilianskaia', 0, 0, 0, 0, 1, 'modDocument', 'en', 1, 'ksenia-kobilianskaia', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (34, 1120, 'Reviews of Master Trainer <br>Ksenia Kobilianskaia</br>'),
  (93, 1120, '<p>Hello. My name is Ksenia Kobilianskaia. I am the owner of LBar micropigmentation studio, a permanent makeup artist and a Master Trainer at our permanent makeup school.</p>\r\n<p>When I opened my micropigmentation studio, I realized from the very start that it would be more than just a job or a way to earn money. To me, micropigmentation is a creative pursuit that inspires me not only to devote my skills to it and feel fulfilled, but also to give every client a little more happiness. For me, seeing happy eyes shining with joy as a client looks in the mirror is the greatest achievement. That\'s exactly why I don\'t stop at what I\'ve already achieved, but stay motivated to keep improving. I\'ve completed dozens of training and advanced courses and taken part in various offline and online events.</p>\r\n<p>Our LBar micropigmentation school has trained more than 400 students to date. Our graduates successfully practice their profession in countries across Europe and Asia and in several US cities. I keep developing my teaching skills in permanent makeup.</p>\r\n<p>My main goal is to give everyone who wants it the opportunity to receive quality training that lays the foundation for a profession they love and ensures them a decent income.</p>\r\n<p>As the owner of the micropigmentation studio and one of its PMU artists, I guarantee that every procedure is performed to a high standard, in full compliance with hygiene and safety standards.</p>\r\n<p>Every semi-permanent makeup artist working at our studio is not just a professional but a true expert in the field. That\'s why I\'m confident in the services we provide, no matter who performs them: me or another PMU artist on our team. Creating a natural look is very important to us. We are advocates of natural beauty. And that means you won\'t be disappointed with the result. I assure you there will be no garish colors or strange shapes. Only elegant transformation and femininity!</p>');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1121, 'document', 'text/html', 'Permanent makeup artist Aliona Șubcinskaia: work photos and reviews', 'Aliona Șubcinskaia – PMU artist: bio, portfolio photos, reviews', 'Permanent makeup artist in Bucharest – Alena Shubchinskaia. About the artist, photos of her work and client reviews. Read and leave a review – LBar Studio', 'aliona-subcinskaia', '', 1, 0, 0, 1100, 0, '', '', 1, 13, 1, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Alena Shubchinskaia', 0, 0, 0, 0, 1, 'modDocument', 'en', 1, 'aliona-subcinskaia', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (34, 1121, 'Reviews of PMU artist <br>Alena Shubchinskaia</br>'),
  (93, 1121, '<p>It\'s a pleasure to welcome you. My name is Aliona, I\'m a permanent makeup artist at Studio LBar, and I\'ve been working in this field for more than 5 years.</p>\r\n<p>What does semi-permanent makeup mean to me? First and foremost, it\'s the chance to help women become more attractive, more feminine, more elegant and more self-confident. I personally understand how important a natural look is and how much beauty matters to every woman. That\'s exactly why, in my work, I avoid flashy colors and harsh, unnatural shapes with unpredictable, unattractive results.</p>\r\n<p>In addition, thanks to strict sterility and hygiene standards, you\'ll get the semi-permanent makeup of your dreams in conditions that are completely safe for your health and your skin.</p>\r\n<p>I\'ll be happy to meet you if you\'re visiting our studio for the first time. As an experienced PMU artist, I\'ll do everything I can to make you feel comfortable. First, we\'ll go over any questions you have, choose the right shade and draw the sketch. I guarantee the procedure will involve minimal discomfort, since I use a quality anesthetic for this purpose. After the procedure, I\'ll recommend how to care for your skin and book you in for a touch-up session.</p>\r\n<p>I want to become the best semi-permanent makeup artist – the one you\'ll want to come back to again and again. As a PMU artist, I assure you that I\'ll do my utmost to give you a result that exceeds your expectations.</p>');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1123, 'document', 'text/html', 'Eyebrow permanent makeup photos', 'Eyebrow tattoo before and after – permanent makeup photo gallery', 'Eyebrow tattoo photo gallery by the artists of LBar Studio. Before and after photos and videos of our work – right after the procedure and fully healed', 'eyebrow-portfolio-before-after', '', 1, 0, 0, 1100, 0, '', '', 1, 13, 3, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Eyebrow micropigmentation', 0, 0, 0, 0, 1, 'modDocument', 'en', 1, 'eyebrow-portfolio-before-after', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (67, 1123, 'Why the portfolio matters: eyebrow micropigmentation photos before and after the procedure'),
  (68, 1123, '<p>Before you choose an artist for your eyebrow permanent makeup and book a procedure, it\'s important to look at before and after micropigmentation photos. Why? To assess the artist\'s level of training and experience. Photos of semi-permanent eyebrow makeup will help you see whether you want the same result on your own face, whether you like the work and how your brows will look. That\'s why we always recommend reviewing a portfolio of eyebrow micropigmentation work before making your decision.</p>\r\n<p>Photos always reveal an artist\'s level of skill. If the brows look unnatural, the shade is too intense or too light, it doesn\'t match the skin\'s color type, or the portfolio has no or very few eyebrow tattoo photos, any of these can be a reason to turn down that artist and their services.</p>'),
  (69, 1123, '<h2>You\'ve chosen your artist. What can eyebrow permanent makeup do for you?</h2>\r\n<p>Every woman knows how tricky it can sometimes be to get her brows just right. <br />Especially when the hairs grow unruly, are sparse or light in color or, on the contrary, too coarse and thick. Every day you have to stand in front of the mirror, constantly correcting the shape and color with a pencil or another cosmetic product. And then, all day long, you keep checking the mirror to make sure your brows haven\'t lost their look.</p>\r\n<p>Eyebrow micropigmentation eliminates absolutely every hassle of doing makeup in this area. The procedure takes only 1.5 hours and gives your brows a perfect look: color, shape, outline, length, density and thickness. The effect lasts at least 1.5–2 years. Once your brow color becomes very light or fades completely, you can always repeat the eyebrow permanent makeup procedure, choosing whichever technique suits you.</p>\r\n<h3>Key benefits of eyebrow tattooing</h3>\r\n<p>Eyebrow micropigmentation is valuable for more than aesthetics alone. It also helps solve a number of problems that used to cause you discomfort:</p>\r\n<ul>\r\n<li>irregular brow shape, length and color;</li>\r\n<li>sparse brows, hair loss and brows with visible gaps;</li>\r\n<li>a complete absence of brows;</li>\r\n<li>hairs that are too light or gray, which can be covered with a richer, more beautiful shade;</li>\r\n<li>allergic reactions to makeup products;</li>\r\n<li>lack of time for makeup, not feeling up to it, or being unable to do your makeup every day.</li>\r\n</ul>\r\n<p>Whatever you want to achieve with eyebrow permanent makeup, if the procedure is performed professionally, all of these challenges will be solved. You\'ll get fresh-looking brows in a natural shade and shape that suit you perfectly. Provided, of course, that you come to Studio LBar.</p>'),
  (70, 1123, 'brovi21-21.jpg');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1124, 'document', 'text/html', 'Permanent eye (eyelid) tattoo photos', 'Eye tattoo before/after: lash line, classic & shaded liner | LBar', 'Photo gallery of eye (eyelid) tattoos by the LBar studio artists. Before and after photos and videos of our work, right after the procedure and fully healed', 'eye-portfolio-before-after', '', 1, 0, 0, 1100, 0, '', '', 1, 13, 4, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Eye micropigmentation', 0, 0, 0, 0, 1, 'modDocument', 'en', 1, 'eye-portfolio-before-after', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (67, 1124, 'Take a look at our eye micropigmentation photos'),
  (68, 1124, '<p>When it comes to permanent eye makeup, keep in mind that the effect will change your appearance for at least 2 years. So, to be happy with the final result, it\'s essential to look at the eye micropigmentation photos in a particular artist\'s portfolio. Photos of semi-permanent eye makeup will also help you assess the artist\'s level of skill. Images of an eyelid tattoo<br />will show how experienced the artist is and which techniques they use.</p>\r\n<p>By reviewing a portfolio of semi-permanent eye makeup work, you can tell whether the artist is right for you, whether you want to book with them, and whether you\'d like a similar eyeliner tattoo. Quality photos reveal a lot and will help you make the right decision.</p>'),
  (69, 1124, '<h2>Have you decided to get semi-permanent eye makeup?</h2>\r\n<p>It\'s an excellent choice, and we\'re sure you\'ll be pleased with the result. In fact, eye micropigmentation gives you not only self-confidence, but also:</p>\r\n<ul>\r\n<li>it transforms your look, making your eyes appear bigger and your lashes longer;</li>\r\n<li>it helps visually change the shape of your eyes. For example, if your eyes are set too close together, a beautiful contour of optimal shape and thickness can make them appear farther apart. Or it can make your eyes look bigger;</li>\r\n<li>it helps camouflage any imperfections in the tattooed area: small scars, droopy eyelids, expression lines, pigmentation spots, vitiligo, etc.;</li>\r\n<li>it cuts down your makeup time – especially if you find it hard to draw straight, even lines.</li>\r\n</ul>\r\n<p>So all you need to do is look at eye tattoo photos and choose the right technique. There are 3 main styles to choose from: upper/lower lash line enhancement, classic eyeliner and eyeliner with shading. When choosing a semi-permanent eye makeup technique, weigh the pros and cons of each one to see exactly which suits you best. You can always consult the artist before the procedure to choose the technique. The artist will take into account the shape of your face and eyes, as well as your preferences. Browse our artists\' portfolios and book your eye micropigmentation at LBar. We\'ll be happy to help you look even more beautiful!</p>'),
  (70, 1124, 'gz4-min1.jpg');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1125, 'document', 'text/html', 'Permanent lip tattoo photos', 'Lip tattoo before/after: aquarelle, 3D/6D, lipstick effect | LBar', 'Photo gallery of permanent lip tattoos by the LBar studio artists. Before and after photos and videos of our work, right after the procedure and fully healed', 'lip-portfolio-before-after', '', 1, 0, 0, 1100, 0, '', '', 1, 13, 5, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Lip micropigmentation', 0, 0, 0, 0, 1, 'modDocument', 'en', 1, 'lip-portfolio-before-after', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (67, 1125, 'Lip micropigmentation photos – a sign of service quality'),
  (68, 1125, '<p>Photos of lip permanent makeup are a deciding factor. They help you see whether you like the artist\'s work, the colors and the lip shape, and whether you\'d like a similar lip tattoo. Lip permanent makeup photos also let you tell whether you\'ve chosen a professional or a beginner.</p>\r\n<p>After all, high-quality photos reveal every detail of the tattoo: how intensely the pigment was implanted, the shade and the final look. That\'s exactly why we recommend reviewing the portfolio of work before you book your lip micropigmentation.</p>'),
  (69, 1125, '<h2>How can you tell if a tattoo artist is a beginner?</h2>\r\n<p>This is where photos of lip permanent makeup can help. If the portfolio has no photos, only a few examples of work, or you don\'t like them, it\'s best not to go to that artist. These signs point either to the artist\'s lack of experience or to cutting corners on materials, which will later affect the quality of the result or your health.</p>\r\n<h3>You like the lip permanent makeup portfolio. What\'s next?</h3>\r\n<p>If the lip tattoo photos catch your eye, feel free to book the procedure. As a result, you\'ll get the effect you want – full, luscious lips in a beautiful, vibrant, softly glossy shade.</p>\r\n<ul>\r\n<li>In addition, lip permanent makeup helps you:</li>\r\n<li>visually change the shape and volume of your lips, making them look symmetrical and full;</li>\r\n<li>hide an unnatural color if your lips are pale or bluish;</li>\r\n<li>cover pigmentation spots, freckles, scars, cuts, cold sore marks, etc.;</li>\r\n<li>have expressive, seductive lips.</li>\r\n</ul>\r\n<p>All you have to do is choose the technique. There are several options: aquarelle lips with light shading in pastel and nude shades; ombré lips with intense shading in light shades; and the ombré lips technique with a contour. You can choose the technique that suits you from the lip micropigmentation photos in the artist\'s portfolio, or consult the artist before the procedure. The artist will select the color and shade based on your skin\'s color type and then apply the tattoo to the highest standard.</p>'),
  (70, 1125, 'img-3468-min1.jpg');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1126, 'document', 'text/html', 'Moments from our basic dermopigmentation course', 'Inside our basic dermopigmentation (micropigmentation) course', '', 'training-moments', '', 1, 0, 0, 1100, 0, '', '', 1, 13, 6, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Training moments', 0, 0, 0, 0, 1, 'modDocument', 'en', 1, 'training-moments', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (93, 1126, '<p>Here are some moments from our basic dermopigmentation course. You can see and assess the level of training and the way our classes are taught – and sign up if you\'re interested.</p>\r\n<p>Please note that all the necessary equipment, tools and accessories are included in the course price. We provide:</p>\r\n<ul>\r\n<li>a space for practical classes, fully furnished and with professional lighting;</li>\r\n<li>areas with upholstered chairs for taking notes during theory classes;</li>\r\n<li>a professional micropigmentation machine – the same one we use in our own work;</li>\r\n<li>pigments in a range of shades for brow, lip and eyelid micropigmentation;</li>\r\n<li>a latex practice pad for the first stage of practice;</li>\r\n<li>all single-use consumables: gloves, masks, sheets, etc.;</li>\r\n<li>notebooks and pens for taking notes.</li>\r\n</ul>\r\n<p>So you won\'t have to spend a thing. We\'ve thought of absolutely everything, right down to the snacks during coffee breaks. These moments from our basic dermopigmentation course are further proof of the quality of our training and of the care we take to make every student comfortable. Sign up for the course, become a professional micropigmentation artist and start enjoying the benefits of a new profession.</p>');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1162, 'document', 'text/html', 'Eyeliner micropigmentation in Bucharest', 'Eyeliner micropigmentation in Bucharest, eye tattoo prices | LBar', 'Get eyeliner micropigmentation in Bucharest at Studio LBar ⚡ Artists with 5+ years of experience ✔ Affordable prices ✎ Excellent, natural results guaranteed', 'eyeliner-micropigmentation', '', 1, 0, 0, 1080, 0, '', '', 1, 8, 2, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Eyeliner micropigmentation', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'eyeliner-micropigmentation', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (22, 1162, 'Layer_354-min.jpg'),
  (24, 1162, 'foto1-min.jpg'),
  (26, 1162, 'Eyelid permanent makeup can help you:'),
  (27, 1162, 'Accentuate your eyes'),
  (30, 1162, 'Your eyes will be visibly defined, and your gaze will become more intense and radiant'),
  (31, 1162, 'Photo gallery – eyeliner micropigmentation before and after the procedure'),
  (32, 1162, 'Eye contour tattoo prices in Bucharest at Studio LBar'),
  (34, 1162, 'Permanent eye makeup (eyeliner) reviews from our clients'),
  (35, 1162, 'Eyelid eyeliner micropigmentation'),
  (37, 1162, '[{\"MIGX_id\":\"1\",\"questions-title\":\"How do I choose the right eye contour tattoo shape?\",\"questions-text\":\"<p>First, decide on the shape, length and thickness of the line you like. Look through the artist\'s portfolio or browse photos online. Our studio\'s artists can also help you choose the most suitable eyeliner style based on your preferences and eye shape. Before the procedure, a sketch is drawn, discussed and approved together with you.<\\/p>\"},{\"MIGX_id\":\"2\",\"questions-title\":\"Is there any risk to my eyesight during eye micropigmentation?\",\"questions-text\":\"<p>No, there is no such risk. The artist stretches and holds the eyelid with their fingers so that, even if the client wanted to blink, they couldn\'t. So there is no risk of harming the eyes during cosmetic eyelid tattooing.<\\/p>\"},{\"MIGX_id\":\"3\",\"questions-title\":\"Is eye contour micropigmentation allowed during pregnancy or breastfeeding?\",\"questions-text\":\"<p>The procedure is not recommended for pregnant or breastfeeding women because of the anesthetic used. If you do decide on semi-permanent eyelid makeup, it\'s better to have it done in the third trimester of pregnancy.<\\/p>\"},{\"MIGX_id\":\"4\",\"questions-title\":\"Is eyelid tattooing painful?\",\"questions-text\":\"<p>Any possible discomfort is eased with an initial and a secondary anesthetic. The procedure is never performed without it. That\'s why eyeliner tattooing is considered painless.<\\/p>\"}]'),
  (38, 1162, 'Eyeliner micropigmentation in Bucharest'),
  (39, 1162, 'Perfect, symmetrical eyeliner for a radiant gaze and beautiful eyes'),
  (40, 1162, 'strelkabanner1.jpg'),
  (41, 1162, '<p>Line length and thickness chosen to suit your eye shape <br />Professional hypoallergenic pigments<br />Quick healing and a long-lasting effect of up to 2 years</p>'),
  (45, 1162, 'Eye contour tattoo for a modern look'),
  (46, 1162, '<p>Drawing straight, identical lines every morning is no easy task. With an eyelid tattoo, you won\'t have to anymore. A perfect, symmetrical, well-shaped line will define your eyes for 1.5–2 years and make them look bigger. Eyeliner tattooing makes your lashes look fuller and more natural, with a deeper color, while your face looks fresher and more polished. You won\'t even need cosmetics: a coat of mascara or lash extensions is enough, and you\'ll look gorgeous around the clock. And it doesn\'t matter what you have planned: a sauna, a swim in the pool, a night out at a club or sunbathing on the beach. Whatever you\'re doing, your line won\'t budge, and you\'ll feel far more confident.</p>'),
  (47, 1162, 'An expressive, deep look and a visible transformation, thanks to well-defined eyeliner. Choose from 3 techniques, each delivering flawless results.'),
  (51, 1162, 'Correct your eye shape'),
  (52, 1162, 'A carefully chosen eyeliner shape will make your eyes look bigger and brighter'),
  (53, 1162, 'Look charming'),
  (54, 1162, 'You\'ll look polished 24/7 without having to apply makeup'),
  (64, 1162, '[{\"MIGX_id\":\"1\",\"col-1\":\"Eyeliner micropigmentation\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"2\",\"col-1\":\"Eye contour tattoo with shading\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"6\",\"col-1\":\"Lash line enhancement\",\"col-2\":\"1 hour\",\"col-3\":\"\",\"col-4\":\"800 RON\"},{\"MIGX_id\":\"3\",\"col-1\":\"Correction of another artist\'s work\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"100% of the first session price\"},{\"MIGX_id\":\"4\",\"col-1\":\"Touch-up\",\"col-2\":\"1 hour\",\"col-3\":\"\",\"col-4\":\"400 RON\"},{\"MIGX_id\":\"5\",\"col-1\":\"Refresh within 1 year\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"80% of the original price\"}]'),
  (65, 1162, 'Answers to frequently asked questions'),
  (66, 1162, '/en/portfolio'),
  (67, 1162, 'Why choose eyelid eyeliner micropigmentation: 3 essential points'),
  (68, 1162, '<p>Today, many young women choose eyeliner tattooing, and for good reason. The procedure delivers not only an excellent result but also maximum comfort in everyday life. Just imagine: no more drawing lines every day, checking the mirror every hour to make sure your pencil, eyeshadow or mascara hasn\'t smudged, carrying a makeup bag to keep fixing your line, or wiping pencil marks off your upper eyelids. Semi-permanent eye makeup gives you a natural look and more self-confidence. Whatever you\'re doing, you can be sure your eyeliner won\'t let you down. We guarantee your eyes will always look made up, and your gaze will be intense and radiant.</p>'),
  (69, 1162, '<h2>3 reasons to choose eyelid micropigmentation</h2>\r\n<p>What makes eyelid tattooing stand out? It offers aesthetic benefits on several levels:</p>\r\n<ol>\r\n<li>It\'s genuinely pretty. A fine line, with or without shading, makes your eyes stand out. For day or evening makeup, a little mascara on your lashes is all you need. Semi-permanent eye makeup pairs perfectly with any cosmetics: liquid or powder foundation, concealer, bronzer, powder, primer. You can wear absolutely any kind of makeup and still be sure your tattoo will always look gorgeous.</li>\r\n<li>You\'ll be able to reshape your eyes and hide minor imperfections. Narrow eyes will look bigger, and close-set eyes will look further apart. Eyeliner tattooing will also mask expression lines, lift a drooping eyelid and hide pigment spots or small scars in the area.</li>\r\n<li>You\'ll save a significant amount of time, as well as the money you\'d otherwise spend on cosmetics.</li>\r\n</ol>\r\n<p>It\'s also worth mentioning that the procedure comes in a variety of techniques. You can choose not only classic eyeliner, but also eyeliner with shading of varying intensity, or an upper and lower lash line tattoo. These techniques give you room to experiment. Since the effect lasts up to 2 years, once it fades you can try a different technique for comparison.</p>\r\n<h2>What you should know about eyelid micropigmentation</h2>\r\n<p>Before booking a micropigmentation appointment, it\'s important to know a few details about the procedure.</p>\r\n<h3>There are some contraindications</h3>\r\n<p>These include insulin-dependent diabetes, epilepsy, mental disorders, conjunctivitis, inflammation in the eye area, viral illnesses, pregnancy and breastfeeding. Menstruation is not a contraindication. It\'s also advisable to reschedule the procedure if you feel unwell or have a fever or high blood pressure.</p>\r\n<h3>Weigh the pros and cons of each technique</h3>\r\n<p>Classic eyeliner can be any thickness and length, with any angle of the line. The wider the line, the more visible it will be, so you\'ll always need to wear mascara. Eyeliner with shading doesn\'t go well with blonde lashes: in that case you\'ll need to tint them or apply mascara regularly, or opt for lash extensions. With the upper and lower lash line technique, on the other hand, the lashes don\'t need tinting. The line is barely visible and makes the lashes look longer and darker. However, this technique doesn\'t hide imperfections the way classic eyeliner and shaded eyeliner do.</p>\r\n<h3>Preparing for eye micropigmentation</h3>\r\n<p>Before the procedure, thoroughly remove your eye makeup, including eyeshadow and mascara. If you have lash extensions, have them removed the evening before the procedure. This ensures the extension glue doesn\'t prevent the pigment from reaching every point near your natural lashes. If you wear contact lenses, remember to bring a lens case and solution. Take your lenses out and put them in the case right before the session. Once the procedure is over, you can wear them again. Still, if you can manage with glasses for a few hours, that\'s much better.</p>\r\n<h3>Skin care after the procedure</h3>\r\n<p>An eyeliner tattoo doesn\'t require any special care. Since the skin needs to heal and regenerate on its own, we don\'t recommend that clients use healing ointments. The one exception may be chlorhexidine or a similar antiseptic, which can be applied to the area during the first two days to protect the skin from infection.<br />The main aftercare rule is to keep the area protected while the skin heals. Avoid washing with hot water, steaming your skin, and going to the sauna, tanning salon or pool. Any physical contact with the eyes is off-limits: no scratching and no picking at flaking skin.</p>\r\n<h3>About touch-ups</h3>\r\n<p>A touch-up isn\'t mandatory after eyelid micropigmentation; it\'s entirely your decision. A touch-up helps to fix any flaws that may appear as the skin heals, deepen the color of the line, add shading if needed, and change the length and width of the line. But if you\'re completely happy with the result after the first session, you can skip it. If you\'re unsure, it\'s best to consult your artist, who will certainly suggest the best solution.</p>\r\n<p>Permanent eye makeup gives you both comfort and self-confidence. Choose your technique and book your procedure. For our part, the artists at the LBar studio in Bucharest will make sure your dream of a perfect eyelid tattoo at an affordable price comes true.</p>'),
  (70, 1162, 'seo-img-1.jpg'),
  (156, 1162, '[[$table-three-col-without-top-bl7]]'),
  (275, 1162, '280-600 RON');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1163, 'document', 'text/html', 'Lash line enhancement', 'Lash line enhancement in Bucharest: upper/lower lid prices | LBar', 'Lash line enhancement in Bucharest at LBar⭐️ A flawless look, affordable prices, shape chosen for you⚡️Lasts up to 2 years. ☝️100% natural look. Top artists', 'lash-line-enhancement', '', 1, 0, 0, 1080, 0, '', '', 1, 8, 5, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Lash line enhancement', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'lash-line-enhancement', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (22, 1163, 'mejresnichka-kat.jpg'),
  (24, 1163, 'original_13-min.jpg'),
  (26, 1163, 'Lash line permanent makeup – your best opportunity:'),
  (27, 1163, 'In 1 hour'),
  (30, 1163, 'You get a perfect line that suits any eye shape, with a painless procedure '),
  (31, 1163, 'Photo gallery – upper/lower lash line tattoo before and after the procedure'),
  (32, 1163, 'Lash line enhancement prices in Bucharest at Studio LBar'),
  (34, 1163, 'Lash line semi-permanent makeup reviews from our clients'),
  (35, 1163, 'Lash line enhancement'),
  (37, 1163, '[{\"MIGX_id\":\"1\",\"questions-title\":\"What is the difference between a lash line tattoo and a classic eyeliner?\",\"questions-text\":\"<p>They differ in technique and in the final look. With a classic eyeliner tattoo, the pigment is placed close to the lash line and above it, depending on the chosen width of the line. With a lash line tattoo, the pigment goes right along the lash line, into the gaps where no lashes grow. The entire line is pigmented, so your eyes look bigger and your lashes longer.<\\/p>\"},{\"MIGX_id\":\"2\",\"questions-title\":\"Is there any risk of harming the eyes with a semi-permanent lash line tattoo?\",\"questions-text\":\"<p>The procedure is safe. While working, the experienced artist stretches the eyelid, which is then gently turned and held in place. This rules out any risk of the pigment or the needle reaching the mucous membrane of the eye. What\'s more, even if the client wanted to blink during the procedure, she wouldn\'t be able to. So you can put all fears and doubts about lash line tattooing aside.<\\/p>\"},{\"MIGX_id\":\"3\",\"questions-title\":\"Is upper\\/lower lash line tattooing painful?\",\"questions-text\":\"<p>No. The procedure is painless thanks to an initial and an additional anesthetic. This prevents pain, as well as swelling and pronounced redness of the skin.<\\/p>\"},{\"MIGX_id\":\"4\",\"questions-title\":\"How long does eyeliner lash line enhancement last?\",\"questions-text\":\"<p>Up to 2 years. It depends on factors such as skin type and lifestyle. In older people and those with dry skin, the effect lasts longer than in younger people and those with oily skin.<\\/p>\"}]'),
  (38, 1163, 'Lash line enhancement in Bucharest'),
  (39, 1163, 'A thin, symmetrical eyeliner for expressive eyes and longer-looking lashes, done by a professional permanent makeup artist'),
  (40, 1163, 'port3.jpg'),
  (41, 1163, '<p>Long-lasting effect of up to 2 years<br />The flawless result you\'ve been wanting</p>'),
  (45, 1163, 'Upper/lower lash line tattoo: expressive eyes without makeup'),
  (46, 1163, '<p>A lash line tattoo is radically different from a classic eye contour, both in how it is done and in its effect on the eyes. Unlike an eye contour tattoo, lash line enhancement places the pigment exclusively along the lash line. The fine line is barely noticeable, yet it visually adds depth and length to your lashes, so you no longer need daily mascara for a polished look. That is why this upper/lower lash line technique of permanent eye makeup is so popular with women who want to look well-groomed without relying on extra cosmetics. Which eyeliner tattoo suits you best is up to you: you can opt for a classic eyeliner with the line extended onto the eyelid, or for one with soft shading.</p>'),
  (51, 1163, 'Lasts 2 years'),
  (52, 1163, 'You will look beautiful and well-groomed without mascara or other cosmetics'),
  (53, 1163, '24/7'),
  (54, 1163, 'You will feel more confident and alluring, with long lashes and a captivating gaze'),
  (64, 1163, '[{\"MIGX_id\":\"1\",\"col-1\":\"Lash line enhancement\",\"col-2\":\"1 hour\",\"col-3\":\"\",\"col-4\":\"800 RON\"},{\"MIGX_id\":\"2\",\"col-1\":\"Touch-up\",\"col-2\":\"1 hour\",\"col-3\":\"\",\"col-4\":\"300 RON\"},{\"MIGX_id\":\"3\",\"col-1\":\"Correction of another artist\'s work\",\"col-2\":\"1 hour\",\"col-3\":\"\",\"col-4\":\"100% of the first session price\"},{\"MIGX_id\":\"4\",\"col-1\":\"Refresh within 1 year\",\"col-2\":\"1 hour\",\"col-3\":\"\",\"col-4\":\"80% of the original price\"}]'),
  (65, 1163, 'Answers to questions about lash line enhancement'),
  (66, 1163, '/en/portfolio'),
  (67, 1163, 'Choose to be even more beautiful! Get a permanent eyeliner tattoo'),
  (68, 1163, '<p>Lash line tattooing is a unique technique: no alternative method gives the same effect. The whole secret is that the pigment is placed along the lash line, filling in the gaps between the lashes. As a result, the lash line takes on an even color, and the lashes look noticeably darker and longer. It is an excellent option if you want your lashes to look made up without using mascara. Semi-permanent lash line tattooing is designed not only to give you an attractive look – it can also make every woman\'s life better. Without a doubt, it means clear savings, both of the time spent on daily makeup and of the money set aside for buying cosmetics.</p>'),
  (69, 1163, '<h2>What you should know about lash line tattooing</h2>\r\n<p>Before booking this procedure, we recommend getting familiar with the key aspects of upper/lower lash line tattooing.</p>\r\n<h3>Stages of the lash line enhancement procedure</h3>\r\n<p>Lash line tattooing is the only permanent eye makeup technique that requires no pre-drawn outline – there is simply no need for one. The artist works along the entire length of the lash line. The only exception is when you choose to extend the tip of the line above the eyelid.<br />Before the procedure, the artist applies a numbing cream, then waits 10–20 minutes for the sensitivity to decrease. Then the tattoo is applied. Note that this technique uses an intense black pigment. An additional anesthetic is used during the procedure. It works very quickly, within just a few minutes, and reduces redness and any possible discomfort. At the end of the procedure, the artist will give you skin care advice and recommend the right date for your touch-up.</p>\r\n<h3>About the touch-up</h3>\r\n<p>A touch-up is not considered mandatory for lash line tattooing. However, it is useful if you need to deepen the color of the line (it may become lighter as the skin heals), cover minor flaws or reshape the line with a different technique – for example, by adding shading or extending its tip.</p>\r\n<h3>Before and after the procedure</h3>\r\n<p>Right before the procedure, your makeup must be removed without using oil-based products. If you have eyelash extensions, they also need to be removed, so that the glue and artificial lashes don\'t keep the pigment from reaching every spot next to your natural lashes. If you wear contact lenses, they must be taken out before the procedure, so we recommend bringing a lens case and solution. You can put your lenses back in afterwards.<br />After the procedure, it is important to let the skin heal on its own. You don\'t need to apply any ointment or healing cream: thanks to the professional technique, the skin will recover quickly and without problems. The skin usually heals within the first 5–10 days and then continues to recover for another 2–3 weeks. After 28–30 days, the skin can be considered fully healed, and the touch-up can be done. During recovery, avoid steaming your skin, washing your face with hot water and going to the tanning salon, sauna or pool. Intense workouts should also be avoided. Do not scratch or touch your eyes, and don\'t pick off flaking skin.</p>\r\n<h3>Contraindications</h3>\r\n<p>Upper/lower lash line tattooing is contraindicated for people with diabetes, pregnant women and breastfeeding mothers, and people with epilepsy or mental health disorders. The tattoo cannot be done if you have conjunctivitis. Menstruation is not a contraindication. If you feel unwell or have a fever or high blood pressure, it is best to reschedule the procedure for another day.</p>\r\n<h2>Features of the lash line enhancement technique</h2>\r\n<p>Lash line pigmentation truly transforms your face and highlights your eyes, giving them an expressive, natural look. However, it will not hide imperfections around the eyes the way another technique can. An eyeliner tattoo suits absolutely every woman, regardless of age, skin type or eye shape.</p>\r\n<p>Upper and lower lash line tattooing is in high demand among young women and ladies alike. We guarantee that this procedure is an easy way to forget about cosmetics for a long time while looking well-groomed at any moment and in any situation. So if you want to transform your appearance, get a brighter, more captivating gaze and have lashes that look longer and darker, we highly recommend lash line enhancement in the eyeliner technique at an affordable price at our Lbar studio.</p>'),
  (70, 1163, 'perm-glaz-foto.jpg'),
  (128, 1163, 'Professional materials <br/>and supplies'),
  (129, 1163, 'We use only tested hypoallergenic pigments and professional equipment'),
  (130, 1163, 'Maximum <br/>long-lasting effect'),
  (156, 1163, '[[$table-three-col-without-top-bl7]]'),
  (275, 1163, '280-600 RON');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1167, 'document', 'text/html', 'Lip micropigmentation in Bucharest', 'Lip micropigmentation in Bucharest, lip tattoo prices | LBar', 'Get lip micropigmentation in Bucharest at Studio LBar ⚡ Artists with 5+ years of experience ✔ Affordable prices ✎ Excellent, natural results guaranteed', 'lip-micropigmentation', '', 1, 0, 0, 1080, 0, '', '', 1, 8, 2, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Lip micropigmentation', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'lip-micropigmentation', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (22, 1167, 'Layer_352-min.jpg'),
  (24, 1167, 'original_13-min.jpg'),
  (26, 1167, 'Aquarelle lip micropigmentation and other techniques give you:'),
  (27, 1167, 'A well-groomed look'),
  (30, 1167, 'Even without makeup, lip pigmentation will transform your face, making it look fresher and more attractive.'),
  (31, 1167, 'Photo gallery – lip pigmentation and the aquarelle technique before and after the procedure'),
  (32, 1167, 'Price list: lip micropigmentation and the aquarelle technique in Bucharest'),
  (34, 1167, 'Lip micropigmentation reviews from our clients'),
  (35, 1167, 'Aquarelle lip micropigmentation'),
  (37, 1167, '[{\"MIGX_id\":\"1\",\"questions-title\":\"What lip tattoo techniques are there, and how do I choose?\",\"questions-text\":\"<p>The most popular techniques are aquarelle and ombr\\u00e9. Aquarelle lip tattooing uses nude, pastel shades with delicate pigmentation. The ombr\\u00e9 technique can use intense, fairly bright colors, applied as a denser shade. Ombr\\u00e9 can be done with or without a contour.<\\/p>\"},{\"MIGX_id\":\"2\",\"questions-title\":\"How long does aquarelle lip micropigmentation last?\",\"questions-text\":\"<p>Up to 2 years, depending on how you care for your lips after the procedure, your lifestyle and your body\'s individual characteristics.<\\/p>\"},{\"MIGX_id\":\"3\",\"questions-title\":\"How is aquarelle lip pigmentation different from other techniques?\",\"questions-text\":\"<p>The key feature of an aquarelle lip tattoo is the choice of light shades and delicate pigmentation. As a result, your lips look fresh and natural. They have a soft pink tint, with no bold color that would require mascara and extra makeup to balance it. Your lips will look healthy and fresh. The only drawback of aquarelle lips is that this technique doesn\'t cover a bluish tinge of the skin and doesn\'t add volume, since no contour is used.<\\/p>\"},{\"MIGX_id\":\"4\",\"questions-title\":\"Can lip micropigmentation cause cold sores (herpes)?\",\"questions-text\":\"<p>The procedure doesn\'t cause herpes, because herpes is a viral infection that usually lies dormant in the body. When your immune system is weakened, the virus becomes active and shows up as a blister on the lips. During cosmetic tattooing the skin of the lips is traumatized, which can trigger an outbreak. So if you know you\'re prone to cold sores, it\'s recommended to take antiviral (antiherpetic) medication before and after the procedure to reduce the chance of blisters around the lips. Even if a cold sore does appear, it isn\'t harmful or dangerous. Once it has cleared and the skin has fully recovered, a touch-up can be done and the spot where the sore was can be covered.<\\/p>\"},{\"MIGX_id\":\"5\",\"questions-title\":\"Can I get a lip tattoo during pregnancy?\",\"questions-text\":\"<p>Lip tattooing is contraindicated during pregnancy and breastfeeding, since it is performed using an anesthetic.\\u00a0<\\/p>\"}]'),
  (38, 1167, 'Lip micropigmentation in Bucharest'),
  (39, 1167, 'Expressive, full, gorgeous lips that can transform your look and your mood'),
  (40, 1167, 'gybybanner3.jpg'),
  (41, 1167, '<p>The right shape, with the option to correct flaws<br />The ideal color, with no loud or flashy tones<br />No pain, no scabs and no long healing period</p>'),
  (45, 1167, 'Lip tattoo – a great alternative to lipstick'),
  (46, 1167, '<p>If you use lipstick, gloss or lip liner every day, you know how exhausting it is to check your lips every hour and reapply after every meal and throughout the day. A permanent lip tattoo is an excellent alternative. Besides an always-made-up look, lip micropigmentation lets you hide imperfections in the area, correct the shape, visually add volume and eliminate asymmetry. Even if you don\'t wear cosmetics but want to refresh your look, go for aquarelle lips. Pink, lush, softly full lips are always attractive. You\'ll not only transform your appearance, giving it a fresh, polished look, but you\'ll also feel more confident. Whatever the situation and whatever you\'re doing, your lips will always keep their color and glow.</p>'),
  (47, 1167, 'Sensual, full lips you can\'t take your eyes off. A perfect shade that transforms your whole look. Choose between the aquarelle technique and a lipstick effect.'),
  (51, 1167, 'A way to hide flaws'),
  (52, 1167, 'Lip micropigmentation covers scars and marks, cold sore traces, freckles and other minor imperfections that used to make you feel self-conscious.'),
  (53, 1167, 'A way to correct your lip shape'),
  (54, 1167, 'An aquarelle lip tattoo, or any other technique, will help you hide asymmetry, add volume and correct the corners of your lips.'),
  (64, 1167, '[{\"MIGX_id\":\"1\",\"col-1\":\"Aquarelle lip micropigmentation\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"8\",\"col-1\":\"Powder-effect lip micropigmentation\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"6\",\"col-1\":\"Ombr\\u00e9 lip micropigmentation\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"7\",\"col-1\":\"3D\\/6D lip tattoo\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"2\",\"col-1\":\"Lip contour tattoo with partial fill\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"1100 RON\"},{\"MIGX_id\":\"3\",\"col-1\":\"Correction of another artist\'s work\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"100% of the first session price\"},{\"MIGX_id\":\"4\",\"col-1\":\"Touch-up\",\"col-2\":\"1 hour\",\"col-3\":\"\",\"col-4\":\"400 RON\"},{\"MIGX_id\":\"5\",\"col-1\":\"Refresh within 1 year\",\"col-2\":\"1 hour 30 min.\",\"col-3\":\"\",\"col-4\":\"80% of the original price\"}]'),
  (65, 1167, 'Answers to frequently asked questions'),
  (66, 1167, '/en/portfolio'),
  (67, 1167, 'Aquarelle lips: enjoy all the benefits of lip micropigmentation'),
  (68, 1167, '<p>Lipstick smeared on your face and clothes, strands of hair blown by the wind sticking to your lip gloss, a makeup bag that never leaves your purse, and checking your lipstick every hour to make sure it hasn\'t \"worn off\". Is it worth all that time and stress when there\'s a wonderful alternative to cosmetics – aquarelle lip micropigmentation? Definitely not. A quick, painless procedure spares you all that hassle, lets you forget about lipstick or lip gloss for several years and gives your self-confidence a real boost. Want the same? Then hurry and book an appointment.</p>'),
  (69, 1167, '<h2>What are the benefits of a semi-permanent lip tattoo?</h2>\r\n<p>First of all, it looks beautiful. Your lips look natural and effortless and need no extra care. If you like, you can add a clear lip gloss. Softly pigmented lips draw attention, while the tint gives them freshness and volume and makes them look well cared for. Visually expressive lips make the whole face look neat and polished. Even after a night out partying, a tanning session or a swim in the pool, your lips keep their look. Beyond aesthetics, permanent lip makeup: <br />hides imperfections: scars, marks, cold sore traces, freckles. Absolutely any flaw becomes invisible. No more covering them with a thick layer of lipstick or lip liner;<br />corrects the shape. What\'s more, you don\'t need beauty injections. Your lips will look fuller, plumper and more sensual. You can define your Cupid\'s bow, visually enlarge your upper lip, your lower lip or both, lift drooping lip corners or hide fine lines.<br /> You can get all these benefits from a single procedure that takes up to 2 hours.</p>\r\n<h2>Main stages of lip micropigmentation</h2>\r\n<p>First, the artist gives you a consultation, answers your questions and selects the right pigment. The pigment should be slightly darker than the shade you\'ve chosen, because it lightens during healing; that way you end up with exactly the shade you originally asked for. How the sketch is made depends on the technique. For example, with the aquarelle technique no sketch is drawn. It isn\'t needed, because the artist may go only half a millimeter beyond your natural lip line, visually enlarging the shape. For an ombré lip tattoo, a sketch is created by outlining the edges with a pencil or pen so that the pigment doesn\'t spread beyond them. This creates even proportions, and the client can see what her lips will look like at the end of the session. Before the procedure begins, an initial anesthetic is applied, followed by a 10–20 minute wait for it to take effect and fully numb the area. During the procedure, a secondary anesthetic is applied to relieve pain, redness and swelling. At the end, the artist will give you aftercare advice and schedule your touch-up appointment.</p>\r\n<h3>Touch-up after lip pigmentation</h3>\r\n<p>If you want excellent results and a color that lasts longer, you\'ll need a touch-up. It ensures your lips are fully saturated with color, keeps the effect lasting and eliminates any flaws. This is especially true if a cold sore appears after the procedure and leaves a small wound: the pigment will come away from that spot along with the regenerating skin, so the area needs to be retouched.</p>\r\n<h2>What you should know about lip micropigmentation</h2>\r\n<p>Lip micropigmentation has contraindications. These include insulin-dependent diabetes, HIV, epilepsy, mental disorders, skin inflammation on the lips, cold sores (labial herpes), pregnancy and breastfeeding. Menstruation is not a contraindication. If you feel unwell or have a fever or high blood pressure, it\'s advisable to reschedule the procedure.</p>\r\n<p>Lip pigmentation doesn\'t fully replace Botox or hyaluronic acid injections if you want to add significant volume to your lips. It gives a visual enhancement by choosing the right pigment shade and placing it just over the natural lip line. That said, tattooing and beauty injections can be combined. The Botox treatment comes first, and once the product has settled under the skin, the lip tattoo procedure can be done. Before booking an appointment, we recommend consulting your artist.</p>\r\n<p>Affordable lip micropigmentation in Bucharest can be a great way to feel feminine and look well-groomed. Choose the technique that flatters you most, and our studio will guarantee a precise and safe application.</p>'),
  (70, 1167, 'perm-mak-gub-foto.jpg'),
  (156, 1167, '[[$table-three-col-without-top-bl7]]'),
  (275, 1167, '400-600 RON');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1168, 'document', 'text/html', 'Beauty mark tattoo at Studio LBar', 'Beauty mark tattoo in Bucharest | 2026 prices | Studio LBar', 'Get a beauty mark tattoo in Bucharest at Lbar ⚡️ Artists with 3+ years\' experience. Affordable 2026 prices, custom shape. Lasts up to 2 years, 100% natural look', 'beauty-mark-tattoo', '', 1, 0, 0, 1080, 0, '', '', 1, 8, 11, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Beauty mark tattoo', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'beauty-mark-tattoo', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (24, 1168, 'mushka3-min.jpg'),
  (26, 1168, 'You can get a beauty mark tattoo:'),
  (27, 1168, 'Anywhere on the face'),
  (30, 1168, 'Under the eye, on the cheek, below or above the lip – wherever you choose to tattoo your beauty mark, it will emphasize your features and create an attractive accent'),
  (31, 1168, 'Photo gallery – beauty mark tattoo before and after the procedure'),
  (32, 1168, 'Semi-permanent beauty mark prices in Bucharest at Studio LBar'),
  (34, 1168, 'Beauty mark micropigmentation reviews from our clients'),
  (37, 1168, '[{\"MIGX_id\":\"1\",\"questions-title\":\"How long does a beauty mark tattoo last?\",\"questions-text\":\"<p>On average, up to 2.5\\u20133 years. It depends on where the beauty mark is placed. If clothing often rubs against it (for example, if the tattoo is on the shoulder), the result will stay visible for a shorter time.<\\/p>\"},{\"MIGX_id\":\"2\",\"questions-title\":\"Where is the best place for a semi-permanent beauty mark?\",\"questions-text\":\"<p>The most popular placement is above or below the lip. However, you can have one absolutely anywhere you like. The studio\'s artist will choose the most suitable size based on the shape of your face or body.<\\/p>\"},{\"MIGX_id\":\"3\",\"questions-title\":\"How is the beauty mark shade chosen?\",\"questions-text\":\"<p>The shade is selected individually based on your skin tone. The standard color is brown, in various shades. However, if you have dark skin, you can even go for black. It all depends on your preferences. The lighter your skin and hair, the lighter the pigment shade, so that the beauty mark looks as natural as possible.<\\/p>\"},{\"MIGX_id\":\"4\",\"questions-title\":\"Can a tattoo be applied over a natural mole?\",\"questions-text\":\"<p>It\'s not recommended to touch or traumatize moles you\'ve had since birth, so as not to cause injury.<\\/p>\"}]'),
  (38, 1168, 'Beauty mark tattoo in Bucharest by LBar'),
  (39, 1168, 'A neat beauty mark with a natural shape and color for a feminine, alluring look'),
  (41, 1168, '<p>Long-lasting effect of up to 3 years<br />Color chosen individually for you<br />The perfect shape with a natural look</p>'),
  (45, 1168, 'A semi-permanent beauty mark for a modern look'),
  (46, 1168, '<p>A beauty mark tattoo is for bold women who want to emphasize their femininity and natural beauty. In fact, a beauty mark, especially on the face, has long been considered a symbol of dignity, and it always draws just the right kind of attention. A small beauty mark on the neck, above the lip or on the cheek highlights and accentuates their shape and contour. You\'ll feel much more confident! A semi-permanent beauty mark takes just a few minutes, is a completely painless procedure and delivers stunning results: a detail that draws attention to your look. The effect lasts for 3 years. So for all that time you\'ll feel attractive and charming, and you\'ll fall in love with yourself.</p>'),
  (51, 1168, 'On the body'),
  (52, 1168, 'A beauty mark can be tattooed on any part of the body: shoulder, neck, abdomen. A pretty beauty mark will look natural and alluring'),
  (53, 1168, 'In the décolleté area'),
  (54, 1168, 'A semi-permanent beauty mark will accentuate your figure, draw eyes to you and make you feel even more feminine'),
  (64, 1168, '[{\"MIGX_id\":\"1\",\"col-1\":\"Beauty mark tattoo\",\"col-2\":\"20 minutes\",\"col-3\":\"150 RON\",\"col-4\":\"150 RON\"},{\"MIGX_id\":\"2\",\"col-1\":\"Touch-up\",\"col-2\":\"20 minutes\",\"col-3\":\"50% of the price\",\"col-4\":\"50% of the price\"},{\"MIGX_id\":\"3\",\"col-1\":\"Correction of another artist\'s work\",\"col-2\":\"20 minutes\",\"col-3\":\"100% of the first session price\",\"col-4\":\"100% of the first session price\"}]'),
  (65, 1168, 'Answers to questions about <br>beauty mark micropigmentation</br>'),
  (67, 1168, 'Get a beauty mark tattoo and become even more charming and alluring'),
  (68, 1168, '<p>In the past, anything acquired or inherited made a person feel special. Some birthmarks, such as moles, were even used to read a person\'s future or fate. In the 17th–18th centuries, a beauty mark was considered a symbol of seduction, wealth and prosperity. Women back then wanted a beauty mark on their face so much that they wore special little patches. Today, a beauty mark on the face or body no longer carries any secret meaning. Yet it still sends the same message it did centuries ago.</p>'),
  (69, 1168, '<h2>Ah, that beauty mark...</h2>\r\n<p>You\'re mistaken if you think a beauty mark is just a minor detail. In fact, a beauty mark tattooed in the right spot and in the right shade can have a remarkable effect. See for yourself:</p>\r\n<ul>\r\n<li>A beauty mark tattoo helps restore facial symmetry. It makes the face look visually balanced.</li>\r\n<li>A beauty mark accentuates your look. And it doesn\'t matter where it\'s placed: cheek, face, shoulder, neck, décolleté, abdomen. A cute beauty mark is sure to catch the eye.</li>\r\n<li>A beauty mark draws attention away from any imperfection. In fact, it can become an attractive feature of your look.</li>\r\n</ul>\r\n<p>You\'ve probably noticed that most celebrities have a beauty mark on their face. Just as in the past, it captivates the eye. Many stars have had a beauty mark tattooed. So don\'t hesitate – if you\'d like a neat beauty mark of your own, book an affordable permanent makeup appointment.</p>\r\n<h2>Steps of the semi-permanent beauty mark procedure</h2>\r\n<p>The procedure takes no more than 10–15 minutes. This includes drawing the sketch and choosing the shade that best matches your skin tone. The sketch is very important in this technique: you need to see what the beauty mark will look like and whether it suits the chosen spot. You can change the shade and size. Once the sketch is approved, the artist performs the tattoo. No anesthetic is used during the procedure. For this reason, a beauty mark tattoo can be done for pregnant women and breastfeeding new mothers.</p>\r\n<h3>Contraindications</h3>\r\n<p>Please note that a permanent makeup beauty mark has contraindications. The procedure must not be performed in the following cases:</p>\r\n<ul>\r\n<li>malignant skin tumors;</li>\r\n<li>covering a natural mole;</li>\r\n<li>insulin-dependent diabetes;</li>\r\n<li>human immunodeficiency virus (HIV), AIDS;</li>\r\n<li>epilepsy;</li>\r\n<li>nervous disorders;</li>\r\n<li>viral illnesses.</li>\r\n</ul>\r\n<p>We recommend rescheduling the procedure if you feel unwell or have a fever or high blood pressure.</p>\r\n<h2>Beauty mark micropigmentation, part of your playful look</h2>\r\n<p>It doesn\'t matter how old you are. A tattooed beauty mark looks beautiful and charming at any age. It suits absolutely every woman, whatever her skin type. So take a step toward femininity, self-assertion and self-confidence. Get an affordable semi-permanent beauty mark and enjoy all the benefits of this amazing offer.</p>'),
  (70, 1168, 'mushka11-min.jpg'),
  (128, 1168, 'Professional materials <br/>and supplies'),
  (129, 1168, 'We use only tested hypoallergenic pigments and professional equipment'),
  (130, 1168, 'Maximum <br/>long-lasting effect'),
  (131, 1168, 'A gorgeous, natural effect for up to 3 years and a perfect look'),
  (275, 1168, '150-150 RON');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1171, 'document', 'text/html', 'Eyebrow, eye and lip micropigmentation reviews', 'Brow, eye & lip permanent makeup reviews, Bucharest | Studio LBar', 'Studio Lbar permanent makeup reviews ⭐️ Bucharest: powder brows, brow, lip and eye micropigmentation ⚡️ Lasts up to 2 years. 100% natural look ⚡️ TOP artists', 'reviews', '', 1, 0, 0, 1102, 0, '', '', 1, 16, 1, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Reviews', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'reviews', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (34, 1171, 'Reviews of Studio LBar'),
  (67, 1171, 'Permanent makeup reviews are always welcome'),
  (68, 1171, '<p>The comments you leave about permanent makeup done at LBar inspire us and help us grow and get even better! We value every review, because it makes us feel good and happy. When we receive positive feedback on micropigmentation, we know that all the effort and perseverance we\'ve put into our work and development have not been in vain. Each of our artists strives to bring beauty to everyone, every day.</p>\r\n<p>If we receive a negative review of micropigmentation, it\'s always a reason to resolve and eliminate the problem so that we never repeat the same mistake. We\'re ready to respond to every review. If a client isn\'t happy with something, we\'ll solve the problem and put things right. That\'s why all reviews of eyebrow, lip or eye micropigmentation are extremely important to us.</p>'),
  (69, 1171, '<h2>Permanent makeup reviews are always welcome</h2>\r\n<p>Reviews of eyebrow permanent makeup can be really helpful to other women. When you\'re choosing a studio for brow, lip and eyelid tattooing in Bucharest, reviews of the services and the artists are a deciding factor. Just looking at photos of an artist\'s work isn\'t enough. Women looking for a cosmetic tattoo studio in Bucharest often read reviews to learn about the level of service, the quality of the work, how the skin healed and how the client felt after leaving the permanent makeup studio. That\'s why we ask you to leave an honest, sincere and truthful review of your micropigmentation at Studio LBar.</p>'),
  (70, 1171, 'brovi21 (13).jpg'),
  (157, 1171, 'gallerchec');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1177, 'document', 'text/html', 'Micropigmentation gift voucher', 'Permanent makeup & powder brows gift voucher in Bucharest | LBar', 'Buy a gift certificate for eye, brow or aquarelle lip micropigmentation in Bucharest – give your wife or girlfriend a Studio LBar voucher for a special occasion', 'gift-voucher', '', 1, 0, 0, 1080, 0, '', '', 1, 3, 18, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Gift voucher', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'gift-voucher', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (61, 1177, '33'),
  (62, 1177, '333'),
  (70, 1177, 'skolko-min.jpg'),
  (93, 1177, '<p>Looking for a special, memorable gift for your girlfriend, mother, wife, daughter, grandmother or colleague for a special occasion? Consider it found. A gift certificate for micropigmentation – semi-permanent makeup on any area or powder brows – will outshine any other gift.<br />Remember that every woman wants to look well-groomed and youthful at all times. Cosmetic tattooing can successfully correct any imperfection. Plus, semi-permanent brow makeup and powder brows never lose their appeal over the years and will always be within reach.</p>\r\n<p>Terms for buying a permanent makeup gift certificate:</p>\r\n<ul>\r\n<li>The minimum value of the certificate is 400 RON, with no limit on higher amounts. You can buy a voucher for a cosmetic tattoo on one, two or three areas at Studio LBar in Bucharest.</li>\r\n<li>The gift certificate is valid for 1 year from the date of purchase.</li>\r\n<li>It is valid for all techniques: powder brows, eyebrow micropigmentation, aquarelle lip tattoo, eyeliner tattoo or semi-permanent eyelid makeup.</li>\r\n<li>The voucher is valid for adults only.</li>\r\n<li>The certificate cannot be forged – it carries a custom holographic sticker. It comes packed in a Studio LBar gift envelope.</li>\r\n</ul>\r\n<p>A gift like this brings the recipient genuine joy. Permanent makeup can transform your appearance, highlight your best features and camouflage minor flaws. It was created to give beauty and self-confidence. Buy a cosmetic tattoo voucher in Bucharest, and we\'ll send it by courier to any town in the country.</p>'),
  (157, 1177, 'gallerchec'),
  (158, 1177, 'Buy a gift voucher'),
  (159, 1177, 'Pick it up at our studio or order delivery by courier'),
  (271, 1177, 'Buy a voucher');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1626, 'document', 'text/html', 'Classic eyelash extensions', 'Classic eyelash extensions in Bucharest. Lash prices at Lbar', 'Classic eyelash extensions in Bucharest at Studio LBar ⚡ Artists with 5+ years\' experience ✔ Modern techniques ✔ Affordable prices ✎ Natural results guaranteed', 'classic-eyelash-extensions', '', 1, 0, 0, 1080, 0, '', '', 1, 8, 4, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Eyelash extensions', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'classic-eyelash-extensions', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (22, 1626, 'mejresnichka-kat.jpg'),
  (24, 1626, 'original_13-min.jpg'),
  (26, 1626, '3 reasons to get eyelash extensions'),
  (27, 1626, 'Less time spent on makeup'),
  (30, 1626, 'No more spending money on mascara and trying to coat your lashes without clumps or stuck-together hairs. Volume or classic lash extensions – your eyes look flawless even when you\'ve just woken up.'),
  (31, 1626, 'Photo gallery – eyelash extensions before and after the procedure'),
  (32, 1626, 'Classic eyelash extension prices in Bucharest at Studio LBar'),
  (34, 1626, 'Eyelash extension reviews from our lovely clients'),
  (35, 1626, 'Lash line enhancement'),
  (37, 1626, '[{\"MIGX_id\":\"4\",\"questions-title\":\"What types of eyelash extensions are there?\",\"questions-text\":\"<p>In general, they differ in three ways:<\\/p>\\n<ul>\\n<li>Length. It ranges from 4 to 20 mm. Short extensions are applied to the lower lid, while the rest are attached to different areas of the upper lid. Our clients usually prefer a maximum length of 12\\u201313 mm.<\\/li>\\n<li>Thickness. It ranges from 0.03 to 0.25 mm. The thinnest are used for 6D and higher-volume lashes, and the thickest for the most natural effect. We recommend a thickness of 0.07 mm for 3D lashes and 0.1\\u20130.12 mm for 2D lashes. Classic eyelash extensions are made with 0.15 mm fibers.<\\/li>\\n<li>Curl. It can be used to visually correct the shape and size of the eyes. There are eight types of curl, but only four are commonly used.<\\/li>\\n<\\/ul>\"},{\"MIGX_id\":\"5\",\"questions-title\":\"Which eyelash extension techniques are used at the LBar salon?\",\"questions-text\":\"<p>Our lash stylist is a true professional who masterfully performs every eyelash extension technique:<\\/p>\\n<ul>\\n<li>classic lashes \\u2013 one artificial lash is applied to each natural lash. They subtly enhance the intensity of your gaze and suit young women.<\\/li>\\n<li>2D lashes \\u2013 two extensions are applied to one natural lash. They look natural and add expressiveness to the eyes.<\\/li>\\n<li>3D lashes \\u2013 a fan of 3 extensions is applied to a natural lash. They add volume and density \\u2013 an excellent option for ambitious women.<\\/li>\\n<li>3D\\u20136D lashes \\u2013 a fan of 3\\u20136 extensions is applied the same way. They suit those with sparse natural lashes and give density and pronounced volume.<\\/li>\\n<li>6D\\u201312D lashes \\u2013 the same lash-by-lash method, except that a fan of 6\\u201312 extensions is applied. They make your gaze expressive and double the volume.<\\/li>\\n<\\/ul>\\n<p><span id=\\\"docs-internal-guid-cc2d21ff-7fff-04aa-b092-42af563ac38e\\\"><span>The price of eyelash extensions varies depending on the technique you choose.<\\/span><\\/span><\\/p>\"},{\"MIGX_id\":\"6\",\"questions-title\":\"How long does the procedure take?\",\"questions-text\":\"<p>Depending on the technique, the procedure can take from 1 to 3 hours. The higher the lash density, the longer the specialist needs to work. Removing lash extensions takes 15\\u201330 minutes.<\\/p>\"},{\"MIGX_id\":\"7\",\"questions-title\":\"How many extensions are applied to each eye?\",\"questions-text\":\"<p>The number of lashes used depends on the density of your natural lashes and the volume you want. Each eye may need anywhere from 100 to 750 lash extensions.<\\/p>\"},{\"MIGX_id\":\"8\",\"questions-title\":\"Will people notice I\'m wearing lash extensions?\",\"questions-text\":\"<p>The lash stylist aims to create the most natural effect possible by choosing a medium length and a moderate number of lashes. People around you will notice the change, but visually the extensions will be impossible to tell apart from your natural lashes. If you want a doll-eye effect, the specialist\'s work will be visible, but the lashes won\'t look artificial \\u2013 they\'ll look authentic and natural.<\\/p>\"}]'),
  (38, 1626, 'Classic eyelash extensions'),
  (39, 1626, 'An expressive look without makeup – lash extensions that last up to 5 weeks'),
  (40, 1626, 'resnitsabanner1.jpg'),
  (41, 1626, '<p>Full, lightweight lashes tailored to the shape of your face and eyes<br />The flawless result you\'ve been wanting<br />A pleasant procedure – relax on a comfortable couch and leave it to the specialist</p>'),
  (45, 1626, 'Eyelash extensions – beauty and comfort every day'),
  (46, 1626, '<p>Applying mascara every day and taking it off every night can get tiring. Often there just isn\'t enough time for it in the morning or enough energy left in the evening. <br />Lash extensions take these steps out of your daily routine, freeing up time for other things that matter just as much. A gorgeous gaze becomes your go-to beauty accessory at any time of day or night, whatever the weather and whatever the occasion. Full, beautifully curled lashes suit both casual and elegant looks and give you confidence in any situation: even in the rain, your eyes will look fresh, with no smudges of black mascara.</p>'),
  (51, 1626, 'Eye shape correction'),
  (52, 1626, 'Well-placed volume makes your eyes look visually larger, and if you like, you can create a fox-eye or almond-eye effect.'),
  (53, 1626, 'Confidence at every moment'),
  (54, 1626, 'Your lashes look natural, beautiful and captivating – you\'ll always know you look stunning, even without makeup.'),
  (64, 1626, '[{\"MIGX_id\":\"6\",\"col-1\":\"Classic (1:1)\",\"col-2\":\"\",\"col-3\":\"180\",\"col-4\":\"\"},{\"MIGX_id\":\"7\",\"col-1\":\"2D volume\",\"col-2\":\"\",\"col-3\":\"200\",\"col-4\":\"\"},{\"MIGX_id\":\"8\",\"col-1\":\"3D volume\",\"col-2\":\"\",\"col-3\":\"240\",\"col-4\":\"\"},{\"MIGX_id\":\"9\",\"col-1\":\"MEGA volume \\/ Hollywood effect \\/ 6D-12D\",\"col-2\":\"\",\"col-3\":\"300\",\"col-4\":\"\"},{\"MIGX_id\":\"10\",\"col-1\":\"Eyelash extension removal\",\"col-2\":\"\",\"col-3\":\"50\",\"col-4\":\"\"}]'),
  (65, 1626, 'Answers to frequently asked questions'),
  (67, 1626, 'Why are eyelash extensions so popular?'),
  (68, 1626, '<p>Unlike strip lashes, eyelash extensions look very natural. They blend in with your own lashes, adding volume, length and a beautiful curl. Well-done extensions last up to 5–6 weeks, and throughout that time you don\'t need mascara or eyeliner – your eyes look expressive and attractive every day and in any situation. All you need is a quick mini touch-up as your natural lashes shed, which is a completely normal process. It\'s much cheaper, more pleasant and simpler than putting on and taking off eye makeup every day.</p>'),
  (69, 1626, '<h2>Benefits of classic eyelash extensions</h2>\r\n<p><strong>Eyelash extensions</strong> give you more than just a beautiful look – they come with plenty of other advantages:</p>\r\n<ul>\r\n<li>Safe for your natural lashes. Mascara and other decorative cosmetics can damage natural lashes, thin them out and even make them fall out. With extensions made from quality materials and a hypoallergenic adhesive, your lashes look well-groomed without being harmed and get a chance to \"rest\" from the negative effects of cosmetics.</li>\r\n<li>Confidence. When you know your eyes look as if a makeup artist had just done them, you feel more confident and in a better mood. What\'s more, there\'s nothing to worry about: artificial lashes won\'t let you down the way mascara does when it clumps or runs.</li>\r\n<li>Time savings. You gain an extra 10–20 minutes every morning and evening for other enjoyable things.</li>\r\n<li>A wide variety of styles. Extensions in various materials, in any technique and style – all to the client\'s taste and suited to her facial features. Your eyes can dramatically transform your whole look.</li>\r\n<li>Camouflages signs of aging. Full lashes draw attention away from fine lines and make your gaze look fresher.</li>\r\n</ul>\r\n<h2>How are classic eyelash extensions applied at the LBar salon in Bucharest?</h2>\r\n<p>The procedure is fairly complex and meticulous, and it requires professional training and a solid command of every technique. It goes like this:</p>\r\n<ul>\r\n<li>Preparation. The lash stylist carefully removes your eye makeup and cleanses the skin around the eyes with a cleansing foam or micellar water. The cleanser is oil-free so that it doesn\'t interfere with applying the extensions.</li>\r\n<li>Isolating the lower eyelid and lower lash line. Eye patches are used for this. They don\'t cause any discomfort or bother you.</li>\r\n<li>Cleansing. Using a special product, the specialist removes excess oil from the skin to ensure a strong adhesive bond.</li>\r\n<li>Applying the primer. It cleanses the lashes and opens the cuticle for a secure hold. The stylist applies a small amount of product with a micro brush.</li>\r\n<li>Preparing the lashes. They are placed on a palette and sorted by length and curl.</li>\r\n<li>Lash extension. This is done according to the chosen technique and style. At the end, the stylist checks that the extensions are firmly attached.</li>\r\n<li>Applying the sealant. The product is applied to the root area to form a protective film that lasts for three days.</li>\r\n<li>Combing the lashes. This sets them in the desired direction. Depending on the chosen technique, the stylist uses a silicone or nylon brush.</li>\r\n<li>Removing the patches and showing the client the result. The procedure is now complete, and you can enjoy the result.</li>\r\n</ul>\r\n<p>Our lash stylist will advise you on how to care for your lashes and when you\'ll need a touch-up.</p>\r\n<h2>About touch-ups</h2>\r\n<p>Touch-ups are done every 2–4 weeks, depending on the type and condition of your natural lashes. A single eyelash has a \"life cycle\" of about 6–8 weeks. At the time of the extension, each lash is at a different stage: some have just grown in, others are midway through their life cycle, and others are about to fall out. It\'s normal for a few lashes to shed soon after the procedure – this won\'t affect the overall look, especially with 2D, 3D and higher-volume lash extensions. A touch-up is only needed once a significant number of lashes have fallen out. During it, the specialist fills the gaps with new artificial lashes and partially replaces the remaining extensions. A lash extension touch-up in Bucharest by our stylist gives you a unique effect for up to 8 weeks.</p>\r\n<h2>Aftercare for eyelash extensions</h2>\r\n<p>To keep your lash extensions looking lush for as long as possible, proper aftercare is essential:</p>\r\n<ul>\r\n<li>Don\'t use oily-textured cosmetics around the eyes. This applies to all cosmetics except powder products.</li>\r\n<li>Don\'t use patches or other products for the under-eye area and eyelids.</li>\r\n<li>Don\'t apply mascara to your lashes.</li>\r\n<li>Don\'t rub your eyes, as you can break or even pull out your natural lashes – and the extensions along with them.</li>\r\n<li>Use water-based, oil-free makeup removers – oil can damage the lash adhesive.</li>\r\n<li>Cleanse your eyes once a day with an eye-cleansing solution to remove makeup residue, dust and excess sebum. Don\'t skip this step: sebum and makeup products can break down the adhesive, and the extensions will fall out too soon. Don\'t be afraid of water – it doesn\'t affect the materials in any way.</li>\r\n</ul>\r\n<h3>Classic eyelash extensions – the choice of modern women</h3>\r\n<p>The first false eyelashes appeared in 1916, thanks to film director D. W. Griffith. Over the more than 100 years since, they have undergone major transformations, and the technology has advanced considerably. Today, high-quality materials and clear and black hypoallergenic adhesives are used, along with a range of techniques and combinations – all to create a look that is as natural as possible, yet expressive and attractive. The most important thing is to combine your wishes with what perfectly suits your features. The specialists at LBar studio will help you find the best solution and make your look brighter, more elegant and more attractive.</p>'),
  (70, 1626, 'perm-glaz-foto.jpg'),
