INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1627, 'document', 'text/html', 'Laser hair removal in Bucharest', 'Permanent laser hair removal in Bucharest ᐈ Prices | LBar', 'Laser hair removal in Bucharest at LBar salon ⚡ Specialists with 5+ years of experience ✔ Modern diode laser ✔ Affordable prices ✎ High-quality equipment', 'laser-hair-removal', '', 1, 0, 0, 1080, 0, '', '', 1, 8, 6, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Laser hair removal', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'laser-hair-removal', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (22, 1627, 'mejresnichka-kat.jpg'),
  (24, 1627, 'bannerlaser1-min.jpg'),
  (26, 1627, '3 reasons to choose laser hair removal'),
  (27, 1627, 'Long-lasting results for up to 10 years.'),
  (30, 1627, 'Only laser hair removal gives you such a long-lasting effect: put away the razor, wax and epilator for a long time and enjoy smooth skin without the hassle.'),
  (32, 1627, 'Laser hair removal prices in Bucharest at Studio LBar'),
  (33, 1627, '<p>FULL BODY includes full legs, arms, underarms, full bikini and intergluteal area</p>\r\n<p>FULL COSMO BODY includes all body areas</p>'),
  (34, 1627, 'Diode laser hair removal reviews from our lovely clients'),
  (35, 1627, 'Lash line enhancement'),
  (37, 1627, '[{\"MIGX_id\":\"4\",\"questions-title\":\"How does a laser hair removal session work?\",\"questions-text\":\"<p>The key principle of laser hair removal is that the laser beam penetrates the skin and is absorbed by melanin \\u2013 the dark pigment in the structure of the hair. Melanin is present in all hair types, but in different amounts: the more there is, the darker the hair and the stronger the effect. Under the beam, the melanin heats up intensely, and the heat is transferred to the follicle, which is destroyed by the high temperature. We also apply special cooling gels so that you don\'t feel any burning, and we use the innovative D-Las 120 Plus long life (Zenith) diode laser, equipped with an innovative handpiece and an efficient cooling system. In addition, we adjust the equipment to each client\'s needs to prevent discomfort and burns.<\\/p>\"},{\"MIGX_id\":\"9\",\"questions-title\":\"What does the procedure involve?\",\"questions-text\":\"<p>Laser hair removal on the legs, underarms, bikini area and even the face is very popular, because it is a painless, safe procedure with long-lasting results. Whatever the area being treated, the LBar salon uses a diode laser with a wavelength of 808 nm. The radiation is absorbed by the melanin in the hair and by the hemoglobin in the blood vessels that nourish the hair follicle.<\\/p>\\n<p dir=\\\"ltr\\\">First, the specialist applies an IPL conductive gel and then goes over the skin centimeter by centimeter with a handpiece that emits constant laser pulses. As the rays are absorbed, heat is released, which destroys the hair follicle and seals the vessel that feeds it.\\u00a0<\\/p>\\n<p dir=\\\"ltr\\\">2\\u20133 weeks after the treatment, the remaining hair and its root fall out and don\'t grow back.<\\/p>\\n<p dir=\\\"ltr\\\">The skin contains no pigment, so the laser does not affect it. Please note: tanned skin does contain pigment, so wait until your tan has faded a little to avoid burns.<\\/p>\\n<p dir=\\\"ltr\\\">After the procedure, the medical aesthetician applies a moisturizing, healing cream with panthenol and removes the excess 15 minutes later. That completes the hair removal session, and you can return to your usual activities.<\\/p>\"},{\"MIGX_id\":\"10\",\"questions-title\":\"How many sessions are needed for complete laser hair removal?\",\"questions-text\":\"<p>Most hairs (about 80%) are in a dormant \\u201cmode\\u201d. The laser acts only on actively growing hair follicles. That is why the first session removes up to 20% of unwanted hair. A few weeks later, other follicles become active and start growing. Sometimes, after 2\\u20133 sessions, the amount of hair even increases, because many dormant bulbs have been activated. Over the following sessions, all these hairs will be removed. A break of one month is recommended between the first and second sessions, and 1\\u20131.5 months between all subsequent sessions.<\\/p>\\n<p>The specialist draws up an individual hair removal plan for each client, taking into account skin phototype, hair texture and color, and the client\'s health, including any hormonal imbalances. In many cases, 5\\u20138 sessions are enough; sometimes 10 may be needed.<\\/p>\\n<p>Permanent laser hair removal on the face is more complicated. Facial hair growth depends heavily on hormone levels, so it is not easy to choose the right moment for the procedure. Often, 12\\u201315 sessions are needed to achieve a guaranteed result.<\\/p>\"},{\"MIGX_id\":\"11\",\"questions-title\":\"How long does each diode laser hair removal session take?\",\"questions-text\":\"<p>The length of a session depends on the size of the area to be treated and on the number of pulses. Thanks to the innovative, high-performance D-Las 120 Plus long life (Zenith) laser, hair removal takes less time. On average, a session may take:<\\/p>\\n<ul>\\n<li>arms, back \\u2013 30 minutes;<\\/li>\\n<li>legs \\u2013 50\\u201360 minutes;<\\/li>\\n<li>hips \\u2013 35 minutes;<\\/li>\\n<li>abdomen \\u2013 15 minutes;<\\/li>\\n<li>underarms \\u2013 20 minutes;<\\/li>\\n<li>face \\u2013 25 minutes;<\\/li>\\n<li>upper lip area \\u2013 10 minutes;<\\/li>\\n<li>bikini area \\u2013 20 minutes.<\\/li>\\n<\\/ul>\\n<p><br \\/>The device is adjusted to each individual client, taking into account body characteristics and skin phototype, which also determines the length of the session.<\\/p>\"},{\"MIGX_id\":\"12\",\"questions-title\":\"How long do laser hair removal results last?\",\"questions-text\":\"<p>Completing the full hair removal course gives you smooth skin for at least 5 years, and with stable, healthy hormone levels and annual maintenance sessions, the result lasts up to 10 years. No other method of removing unwanted body hair offers such a long-lasting effect. Once you have completed the full course, you can forget about shaving, depilation, sugaring and the like for a long while.<br \\/>The effect can be extended with preventive treatments. These are done once or twice a year for the body and every 3\\u20134 months for the face. Such extra sessions are especially necessary in cases of strong hormonal imbalances, which stimulate dormant hair follicles to wake up.<\\/p>\"}]'),
  (38, 1627, 'Laser hair removal in Bucharest'),
  (39, 1627, 'Smooth skin for at least 5 years with painless laser hair removal on any area of the body'),
  (40, 1627, 'bannerepilare-min.jpg'),
  (41, 1627, '<p><span id=\"docs-internal-guid-835b35cd-7fff-32b5-6973-58b52be77b1a\"><span>Effective from the very first session – get 50% off</span></span><br /><span id=\"docs-internal-guid-0988fdae-7fff-843d-30fc-411f0f600f5a\"><span>We work with all skin and hair types, using innovative equipment</span></span><br />Up to 40% off personalized service packages</p>'),
  (45, 1627, 'Laser hair removal – smooth skin, effortlessly'),
  (46, 1627, '<p>Shaving damages the skin, while waxing and sugaring are painful and mean putting up with unwanted body hair for a while – which also limits your plans and undermines your self-confidence. The most comfortable, effective and advanced way to get rid of unwanted hair is laser hair removal. We perform the procedure with the new D-Las 120 Plus long life diode laser, which has an improved cooling system and more precise settings for different skin phototypes. Results are visible from the very first session, with no pain, burns or irritation. All that awaits you are pleasant sensations and amazingly smooth skin 1–2 months after your first session. A full course delivers lasting results for 5–10 years, depending on your skin\'s individual characteristics – our specialist will give you recommendations on this.</p>'),
  (51, 1627, 'Easy and comfortable.'),
  (52, 1627, 'A convenient way to get rid of unwanted hair. The laser causes no pain – you only feel a sensation of warmth on the skin.'),
  (53, 1627, 'Hair-free, with no ingrown hairs.'),
  (54, 1627, 'Besides its main function, the laser also removes hairs that have grown under the skin and prevents new ones from appearing, starting from the very first session.'),
  (64, 1627, '[{\"MIGX_id\":\"6\",\"col-1\":\"Full body (women)*\",\"col-2\":\"500 LEI\",\"col-3\":\"2800 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"7\",\"col-1\":\"Full body Cosmo*\",\"col-2\":\"800 LEI\",\"col-3\":\"4450 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"8\",\"col-1\":\"Underarms\",\"col-2\":\"100 LEI\",\"col-3\":\"560 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"9\",\"col-1\":\"Sideburns\",\"col-2\":\"90 LEI\",\"col-3\":\"500 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"10\",\"col-1\":\"Full face\",\"col-2\":\"160 LEI\",\"col-3\":\"900 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"11\",\"col-1\":\"Forearms\",\"col-2\":\"280 LEI\",\"col-3\":\"1500 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"12\",\"col-1\":\"Arms\",\"col-2\":\"400 LEI\",\"col-3\":\"2250 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"13\",\"col-1\":\"Periareolar area\",\"col-2\":\"80 LEI\",\"col-3\":\"450 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"14\",\"col-1\":\"Bikini line\",\"col-2\":\"130 LEI\",\"col-3\":\"750 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"15\",\"col-1\":\"Full bikini\",\"col-2\":\"250 LEI\",\"col-3\":\"1400 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"16\",\"col-1\":\"Intergluteal area\",\"col-2\":\"80 LEI\",\"col-3\":\"450 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"17\",\"col-1\":\"Buttocks\",\"col-2\":\"200 LEI\",\"col-3\":\"1150 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"18\",\"col-1\":\"Shoulders\",\"col-2\":\"300 LEI\",\"col-3\":\"1650 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"19\",\"col-1\":\"Abdomen\",\"col-2\":\"300 LEI\",\"col-3\":\"1650 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"20\",\"col-1\":\"Belly line (linea alba)\",\"col-2\":\"80 LEI\",\"col-3\":\"450 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"21\",\"col-1\":\"Lower legs\\/thighs\",\"col-2\":\"350 LEI\",\"col-3\":\"1950 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"22\",\"col-1\":\"Full legs\",\"col-2\":\"450 LEI\",\"col-3\":\"2500 LEI\",\"col-4\":\"\"}]'),
  (65, 1627, 'Answers to frequently asked questions'),
  (67, 1627, 'Why has laser hair removal become so popular?'),
  (68, 1627, '<p>In Bucharest, laser hair removal is more in demand than any other in-salon method of removing unwanted hair. That\'s because, with proper home care, it has no side effects, it is painless compared with ELOS and photoepilation, and it delivers a significantly better result.</p>\r\n<p>After diode laser hair removal, you no longer need to shave every day or have regular waxing or sugaring sessions. This frees up a lot of time in your daily routine and saves the money you would normally spend on hair removal products and regular manual hair removal. The laser hair removal procedure is quick and comfortable and, thanks to modern equipment, it is suitable for any woman – not just those with dark hair.</p>'),
  (69, 1627, '<h2>Benefits of laser hair removal</h2>\r\n<p>Laser hair removal on the hips, legs, arms and other areas offers many advantages:</p>\r\n<ul>\r\n<li>\r\n<p style=\"display: inline !important;\">Suitable for the whole body. The device\'s compact handpiece allows high-quality hair removal on any area, including the bikini area.</p>\r\n</li>\r\n<li>Long-lasting effect. New body hair won\'t appear for at least 5 years, and with maintenance sessions once or twice a year, the result can last up to 10 years.</li>\r\n<li>No ingrown hairs. If you have any, they will be removed in the first session, and new ones won\'t appear at all.</li>\r\n<li>No pain. The special cooling system in the handpiece and the use of conductive gel on sensitive areas keep discomfort to a minimum. You may feel warmth or a slight tingling, but never pain or burning.</li>\r\n<li>Safety. The diode laser has no negative effect on the skin or internal organs. It acts exclusively on the hair and the follicle. The radiation does not harm the body and causes no adverse reactions.</li>\r\n</ul>\r\n<h2>How does the procedure work at our laser hair removal studio in Bucharest?</h2>\r\n<p>Your first hair removal session at Studio LBar begins with a meeting with the medical aesthetician, who examines the area to be treated, determines your skin phototype and explains the details of the technique, how the laser acts on the skin and the long-term results you can expect. The specialist will always inform you about the contraindications of the procedure and make sure you don\'t have any of them. Then comes the procedure itself, performed with the D-Las 120 Plus long life diode laser:</p>\r\n<ol>\r\n<li>Both the aesthetician and the client wear special protective goggles that shield the retina from an accidental laser beam.</li>\r\n<li>If the hairs are longer than 2 mm, the specialist trims the excess with a razor unpacked especially for you and discarded afterward.</li>\r\n<li>The aesthetician applies a conductive gel to the treatment area. It is needed to guide the diode beam effectively and to let the handpiece glide smoothly over the skin.</li>\r\n<li>When working on the bikini area or other sensitive areas, we use an anesthetic menthol gel for clients who are sensitive to pain. It has a pronounced pain-relieving and cooling effect.</li>\r\n<li>The specialist treats the skin centimeter by centimeter while keeping an eye on how you feel. Each treatment can take from 10 minutes to 1 hour, depending on the size of the area.</li>\r\n<li>At the end of the session, the conductive gel is removed from the skin and a moisturizing, skin-healing product is applied in its place. The cream always contains panthenol. After 15 minutes, the product is gently removed with a tissue, using light blotting motions.</li>\r\n</ol>\r\n<p>The procedure is performed the same way regardless of the area of the body or face being treated. The skin may redden slightly after the procedure – this fades quickly and leaves no marks. Please note: laser hair removal can be done at any age, once hormone levels have stabilized. On request, it is performed for clients over 14, but keep in mind that the result depends on hormonal fluctuations and may differ from what you expect.</p>\r\n<h3>Laser hair removal in the bikini area</h3>\r\n<p>The bikini area is very sensitive because it has many nerve endings. Local anesthesia is usually used, especially when hair is removed from the intimate area or the panty area. The anesthetic is applied 30–40 minutes before the main procedure, following a scheme similar to that used for other areas of the body. An important point concerns laser hair removal of these areas during your period. In general, it is not contraindicated, but a few things should be taken into account:</p>\r\n<ul>\r\n<li>You need to feel well – don\'t come for the procedure if you have pain or cramps.</li>\r\n<li>Pay special attention to hygiene and use tampons.</li>\r\n</ul>\r\n<h2>Preparing for laser hair removal</h2>\r\n<p>No special preparation with creams is needed before laser hair removal of the underarms or other areas. However, to achieve a high-quality, long-lasting effect, follow a few recommendations:</p>\r\n<ul>\r\n<li>For a few weeks before your visit, avoid exposing the area you plan to treat to the sun. Wear pants, cover your arms, skip crop tops if you are treating your abdomen or back, and so on. No sunbathing during this period.</li>\r\n<li>For 20 days before your first session and throughout the entire course, use only a razor. It is very important not to damage the hair follicles, because they are what absorbs the laser beams – without them, laser hair removal won\'t work. Avoid anything that damages the hair follicle: sugaring, waxing, depilatory creams, electric epilators, etc.</li>\r\n<li>For 3 days before the procedure, avoid lotions and alcohol-based products. This applies only to the areas that will be treated.</li>\r\n<li>On the day of the procedure, but no more than 12 hours before it, shave off the unwanted hair. It\'s not a problem if a few hairs remain in some places – the aesthetician will remove them with a disposable razor blade.</li>\r\n<li>2 weeks before the procedure, you need to stop taking tetracycline antibiotics and also stop anticoagulants and photosensitizing medications. Otherwise, burns and pigment spots may occur.</li>\r\n</ul>\r\n<h2>Skin care after laser hair removal</h2>\r\n<p>In most cases, there are no side effects after laser hair removal. However, slight redness and swelling may sometimes appear, lasting no more than 10 days. If they don\'t cause you discomfort, there is nothing to worry about. Home care simply means treating the area daily with chlorhexidine solution and panthenol.</p>\r\n<p>Avoid sun exposure for 2 weeks. If that\'s not possible, apply plenty of sunscreen to the exposed treated areas before going outdoors, whatever the season.</p>\r\n<h2><span id=\"docs-internal-guid-c51be5b3-7fff-c62c-1137-a698794f1f14\"><span>About the laser</span></span></h2>\r\n<p><span><span>LBar Studio uses one of the most advanced devices available – the D-Las 120 Plus long life diode laser. It meets the standards of innovative, world-class hair removal technology:</span></span></p>\r\n<ul>\r\n<li>The long cable between the device and the handpiece gives the specialist freedom of movement, so sessions take less time.</li>\r\n<li>The modern cooling system is built into the handpiece, so discomfort and pain are completely eliminated.</li>\r\n<li>The diode device has a wavelength of 808 nm – it works in the infrared spectrum, so it acts only on the hairs while the skin remains untouched. The laser destroys only the hair follicles and hair shafts. At the same time, its 2300 W power is enough to ensure maximum performance.</li>\r\n</ul>\r\n<p>This device can be used for various types of procedures:</p>\r\n<ul>\r\n<li>Hair removal without limits – it can be performed on any area of the body.</li>\r\n<li>Removal of ingrown hairs.</li>\r\n<li>Soothing shaving irritation.</li>\r\n</ul>\r\n<h3>Laser hair removal – the No. 1 hair removal method</h3>\r\n<p>Laser hair removal is used by millions of women in many countries. It is convenient, fast and effective compared with other methods of removing unwanted hair from the face and body. Thanks to modern equipment, it can remove not only dark hair, but also red and even light brown hair. The laser frees you from unwanted hair for at least 5 years – you can choose your look freely, without depending on hair removal, and always feel confident in your own beauty, whatever the occasion. The price of laser hair removal at Studio LBar lets you get velvety-smooth skin at a low cost! You can take advantage of a 50% discount on your first session and up to 40% off service packages. Book an appointment with our aesthetician, and we will do everything to make sure you are happy with the procedure and the result.</p>'),
  (70, 1627, 'perm-glaz-foto.jpg'),
  (127, 1627, ''),
  (156, 1627, '[[$table-three-col-bl7]]'),
  (176, 1627, 'Welcome to LBar! I\'m Ksenia Kobilianskaia, your laser hair removal aesthetician'),
  (177, 1627, 'Licensed medical aesthetician with 7 years of full-time experience in the field.'),
  (178, 1627, 'Over 5,000 sessions performed on skin of different phototypes and on all hair colors and types.'),
  (179, 1627, 'Master classes, courses and professional training conferences, plus training on modern equipment – all to deliver work of impeccable quality.'),
  (180, 1627, 'A gentle, friendly and competent approach that creates a pleasant, relaxed atmosphere.'),
  (181, 1627, 'Laser hair removal on any area, including the delicate bikini area, with careful, high-quality anesthesia.'),
  (275, 1627, '80-5000 RON'),
  (302, 1627, '5'),
  (303, 1627, '5');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1629, 'document', 'text/html', 'Manicure in Bucharest at the Lbar salon', 'Manicure Bucharest Sector 1, Dorobanti – gel nails, prices | Lbar', 'Manicure in Bucharest at LBar gel nail salon ⚡ Experienced artists (5+ years) ✔ Sector 1, Dorobanti (Perla stop) ✔ Fair prices ✎ Natural results, guaranteed', 'manicure', '', 1, 0, 0, 1080, 0, '', '', 1, 8, 7, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Manicure', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'manicure', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (31, 1629, 'Gel nail manicures – examples of our work'),
  (32, 1629, 'Prices for classic manicure, gel polish and other nail services in Bucharest'),
  (34, 1629, 'Manicure reviews from our lovely clients'),
  (35, 1629, 'Lash line enhancement'),
  (38, 1629, 'Manicure in Bucharest at the Lbar salon'),
  (39, 1629, 'Soft, smooth hands and well-groomed nails — an important part of feminine beauty'),
  (40, 1629, 'manik3-min.jpg'),
  (41, 1629, '<p><strong>Luxury materials</strong></p>\r\n<p>We use the best brands of materials for a guaranteed flawless result.</p>\r\n<p><strong>Artists with over 5 years of experience</strong></p>\r\n<p>All our work is top level, because it\'s done by professionals, not beginners.</p>'),
  (44, 1629, 'manick141421.jpg'),
  (45, 1629, 'The Lbar salon offers quality and real benefits'),
  (46, 1629, '<p>At our manicure salon in Dorobanti (Perla stop), we have a great offer: a professional manicure with polish for 200 lei.</p>\r\n<p>Our artists gently care for the skin of your hands, create the perfect nail shape and design beautiful nails to complement your natural beauty.</p>'),
  (64, 1629, '[{\"MIGX_id\":\"11\",\"col-1\":\"Gel polish manicure\",\"col-2\":\"\",\"col-3\":\"200 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"6\",\"col-1\":\"Classic manicure with gel polish\",\"col-2\":\"\",\"col-3\":\"200 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"7\",\"col-1\":\"Gel polish manicure with strengthening base\",\"col-2\":\"\",\"col-3\":\"50 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"8\",\"col-1\":\"Gel polish removal\",\"col-2\":\"\",\"col-3\":\"50 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"9\",\"col-1\":\"Stamping (one nail)\",\"col-2\":\"\",\"col-3\":\"10 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"12\",\"col-1\":\"Gel on the natural nail\",\"col-2\":\"\",\"col-3\":\"20 LEI\",\"col-4\":\"\"}]'),
  (67, 1629, 'At Lbar, you can get every type of manicure in Bucharest.'),
  (68, 1629, '<p>We don\'t stop at quality care – we always achieve perfect results with every type of manicure:</p>'),
  (69, 1629, '<ul>\r\n<li>Classic<strong>.</strong> This is the basic cut manicure for women and men. The artist gives the nails the ideal shape and buffs their surface, removing the cuticle with fine scissors or nippers.</li>\r\n<li>European<strong>.</strong> Instead of cutting the cuticle, the artist gently pushes it back toward the nail\'s growth zone with an orange stick. This manicure method is most often preferred in Bucharest by people with thin cuticles. The nail shape is then corrected, followed by buffing.</li>\r\n<li>E-file<strong>.</strong> Using a special device with a range of different bits, the artist gently files the cuticle, gives the nails the desired shape and buffs the nail plate. An e-file manicure helps restore ridged and peeling nails.</li>\r\n<li>SPA manicure<strong>.</strong> Here, more attention goes to the skin of the hands: massage and exfoliation for deep cleansing are followed by an oil treatment that leaves the skin velvety soft. For the nails – standard shaping and buffing.</li>\r\n<li>Polish<strong>.</strong> Application of regular nail polish or gel. We have one of the widest manicure color palettes in Sector 1. Any other type of manicure can be finished with polish – colored or clear.</li>\r\n<li>Men\'s<strong>.</strong> Men\'s manicure is in high demand in Bucharest. It can be done with the classic or the e-file method and may include callus removal, nail shape correction, treating and softening dry patches of skin, and a cream massage. On request, the artist will apply a clear polish to strengthen the nail plate.</li>\r\n</ul>'),
  (70, 1629, 'manik4-min.jpg'),
  (127, 1629, ''),
  (156, 1629, '[[$table-two-col-bl7]]'),
  (273, 1629, 'images/all/manik1-min.jpg'),
  (275, 1629, '50-300 RON'),
  (302, 1629, '5'),
  (303, 1629, '5'),
  (306, 1629, 'hide');
INSERT INTO Impulse_Digital_X_site_content (`id`, `type`, `contentType`, `pagetitle`, `longtitle`, `description`, `alias`, `link_attributes`, `published`, `pub_date`, `unpub_date`, `parent`, `isfolder`, `introtext`, `content`, `richtext`, `template`, `menuindex`, `searchable`, `cacheable`, `createdby`, `createdon`, `editedby`, `editedon`, `deleted`, `deletedon`, `deletedby`, `publishedon`, `publishedby`, `menutitle`, `donthit`, `privateweb`, `privatemgr`, `content_dispo`, `hidemenu`, `class_key`, `context_key`, `content_type`, `uri`, `uri_override`, `hide_children_in_tree`, `show_in_tree`, `properties`, `alias_visible`) VALUES (1631, 'document', 'text/html', 'Pedicure in Bucharest at the Lbar salon', 'Pedicure Bucharest Sector 1, Dorobanti – gel nails, prices | Lbar', 'Pedicure in Bucharest at LBar gel nail salon ⚡ Experienced artists (5+ years) ✔ Sector 1, Dorobanti (Perla stop) ✔ Fair prices ✎ Natural results, guaranteed', 'pedicure', '', 1, 0, 0, 1080, 0, '', '', 1, 8, 8, 1, 1, 1, UNIX_TIMESTAMP(), 1, UNIX_TIMESTAMP(), 0, 0, 0, UNIX_TIMESTAMP(), 1, 'Pedicure', 0, 0, 0, 0, 0, 'modDocument', 'en', 1, 'pedicure', 0, 0, 1, '{\"ms2gallery\":{\"media_source\":\"2\"}}', 1);
INSERT INTO Impulse_Digital_X_site_tmplvar_contentvalues (tmplvarid, contentid, value) VALUES
  (31, 1631, 'Gel nail pedicures – examples of our work'),
  (32, 1631, 'Pedicure and gel polish prices in Bucharest'),
  (34, 1631, 'Pedicure reviews from our lovely clients'),
  (35, 1631, 'Lash line enhancement'),
  (38, 1631, 'Pedicure in Bucharest at the Lbar salon'),
  (39, 1631, 'Caring for the health and beauty of your feet makes every step a pleasure'),
  (40, 1631, 'shop_property_file_606_913.jpg'),
  (41, 1631, '<p><strong>Premium materials</strong></p>\r\n<p>Every material we use has passed our expert screening and performs flawlessly.</p>\r\n<p><strong>Every artist is experienced</strong></p>\r\n<p>Our studio is staffed by artists who have already reached a professional level.</p>'),
  (44, 1631, 'pedi4111.jpg'),
  (45, 1631, 'The Lbar studio looks after your beauty and health'),
  (46, 1631, '<p>A pedicure in Bucharest is especially relevant: in Romania\'s changeable climate, the skin of the feet is exposed to stress, and it\'s important to care not only for its softness but also for its health. The same goes for your nails.</p>\r\n<p>Thickened skin prevents normal air exchange and also impairs signals to the nerve endings, of which there are so many in the soles of the feet. At the Lbar studio, our artists do pedicures for women and men, taking care not only of aesthetics but also of health.</p>\r\n<p>We put a spring in every step! Come for a pedicure in Sector 1 and relax in the comfort of our studio, where every artist performs the procedure professionally and with care – all you have to do is enjoy it!</p>'),
  (64, 1631, '[{\"MIGX_id\":\"11\",\"col-1\":\"Gel polish manicure\",\"col-2\":\"\",\"col-3\":\"200 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"6\",\"col-1\":\"Classic manicure with gel polish\",\"col-2\":\"\",\"col-3\":\"200 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"7\",\"col-1\":\"Gel polish manicure with strengthening base\",\"col-2\":\"\",\"col-3\":\"50 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"8\",\"col-1\":\"Gel polish removal\",\"col-2\":\"\",\"col-3\":\"50 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"9\",\"col-1\":\"Stamping (one nail)\",\"col-2\":\"\",\"col-3\":\"10 LEI\",\"col-4\":\"\"},{\"MIGX_id\":\"12\",\"col-1\":\"Gel on the natural nail\",\"col-2\":\"\",\"col-3\":\"20 LEI\",\"col-4\":\"\"}]'),
  (67, 1631, '6 reasons to book a pedicure in Dorobanți at the Lbar studio:'),
  (69, 1631, '<ul>\r\n<li>Maximum safety. We sterilize our instruments in three stages: disinfection with solutions, hot-air sterilization and UV light. Our core principle is guaranteed safety for the health of our clients and staff.</li>\r\n<li>Every artist is an expert. You entrust your feet to professionals who will not only do quality work, but also help you relax and enjoy pleasant sensations.</li>\r\n<li>All types of pedicure in one place. Our studio has everything it takes to offer clients a choice of different types of pedicure in Bucharest: classic, e-file and medical.</li>\r\n<li>Excellent results. After the procedure, no thickened skin remains – only soft, smooth skin. For this, we use a professional softening and moisturizing cream.</li>\r\n<li>We solve problems. Feet often suffer from ingrown nails, corns and calluses. Our artists know how to deal with each of these issues, so after your pedicure you\'ll feel guaranteed relief.</li>\r\n<li>A pleasant atmosphere and an enjoyable process. Sit back, get comfortable and enjoy the sensations. While the artist works, you can doze off, rest, listen to music and more.</li>\r\n</ul>'),
  (70, 1631, 'pedi777.jpg'),
  (127, 1631, ''),
  (156, 1631, '[[$table-two-col-bl7]]'),
  (273, 1631, 'images/all/manik1-min.jpg'),
  (275, 1631, '50-300 RON'),
  (302, 1631, '5'),
  (303, 1631, '5'),
  (306, 1631, 'hide');
